              <p className="text-xs text-muted-foreground">{[equipo?.serie, equipo?.caracteristicas, equipo?.sistemaOperativo].filter(Boolean).join(" · ")}</p>
              <div className="mt-2 grid grid-cols-4 gap-2 text-sm">

