    setChkFianza(true);
    setRequestId(null);
    setResumen(null);
    setSinFacturaAbierto(false);
    setMotivoSinFactura("");
  }
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [open, alq?.alquilerId]);

if (!alq || !equipo) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
