      ) : (
        <FilaTabla etiqueta="Fianza a devolver al cliente" valor={<span className="text-lg">{euros(liquidacion.fianzaDevolver)}</span>} fuerte clase="bg-emerald-50 dark:bg-emerald-500/10" />
      )}
    </tbody>
  </table>
</div>

