/** Reproduce #modalNuevoEquipo (abrirModalNuevoEquipo/guardarNuevoEquipo) del original. */
export function NuevoEquipoDialog({
  onCreado,
  valoresIniciales,
  origenResguardo,
  trigger,
}: {
  onCreado: () => void;

  /** Precarga campos (p.ej. marca/modelo) al abrir — usado desde Punto Limpio al marcar un equipo "reparable". */
  valoresIniciales?: Partial<DatosNuevoEquipo>;
  /** Resguardo de origen cuando el equipo procede de un reciclaje de Punto Limpio. */
  origenResguardo?: string;
  /** Contenido del disparador; por defecto el botón "Nuevo Equipo" habitual. */
  trigger?: React.ReactNode;
}) {
  const [open, setOpen] = useState(false);
  const [datos, setDatos] = useState<DatosNuevoEquipo>({ ...VACIO, ...valoresIniciales });
  const [enviando, setEnviando] = useState(false);

  function actualizar<K extends keyof DatosNuevoEquipo>(campo: K, valor: DatosNuevoEquipo[K]) {
    setDatos((prev) => ({ ...prev, [campo]: valor }));
  }

  async function guardar() {
    if (!datos.marca.trim()) return toast.error("La marca es obligatoria");
    if (!datos.modelo.trim()) return toast.error("El modelo es obligatorio");
    if (!datos.sistemaOperativo.trim()) return toast.error("El sistema operativo es obligatorio");
    if (!datos.imagenUrl.trim()) return toast.error("La imagen URL es obligatoria para el catálogo web");
    if (!esUrlValida(datos.imagenUrl)) return toast.error("La Imagen URL debe ser una URL válida (debe empezar por https://)");
    if (!esUrlValida(datos.enlaceRepuesto)) return toast.error("El enlace del repuesto debe ser una URL válida (debe empezar por https://)");
    if (!datos.caracteristicas.trim()) return toast.error("Las características son obligatorias");
    const pv = Number(String(datos.precioVenta ?? "").replace(",", "."));
    if (String(datos.precioVenta ?? "").trim() && (!Number.isFinite(pv) || pv < 0)) return toast.error("El precio de venta debe ser un número de 0 o más");

    setEnviando(true);
    try {
      const res = await fetch("/api/equipos", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ ...datos, origenResguardo }),
      });
      const data = await res.json();
      if (!data.ok) throw new Error(data.error || "Error desconocido");
      toast.success(`Equipo ${data.equipo.id_equipo} creado`);
      setDatos({ ...VACIO, ...valoresIniciales });

    setOpen(false);
    onCreado();
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error desconocido");
  } finally {
    setEnviando(false);
  }
}

