  ...(detalle.envioActivado ? [{ descripcion: "Envío a domicilio", cantidad: 1, precio: 0 }] : []),
  ...(detalle.recogidaActivada ? [{ descripcion: "Recogida a domicilio", cantidad: 1, precio: 0 }] : []),
