const duracionAlquiler = { inicial: detalle.duracion, tarifas: detalle.tarifas, equipoNombre: detalle.equipoNombre || "Equipo" };
// Reproduce vfResenaCard tal cual la usa Reparaciones (factura-reparacion-dialog.tsx),
