            // /api/alquileres/[id]/facturas/route.ts (rama
            // alquiler_rectificativa) para no bloquear en el backend.
            yaGenerada={detalle.inicial ? null : detalle.rectificativa}
            corregida={detalle.corregida}
            modoDevolucion
