function fechaCorta(iso: string | null): string {
  if (!iso) return "—";
  const d = new Date(iso);
  return Number.isNaN(d.getTime()) ? "—" : d.toLocaleDateString("es-ES", { timeZone: "Europe/Madrid", day: "2-digit", month: "2-digit", year: "numeric" });
}

/** Buscador de pedidos de reposición de stock (kelatos_app.stock_piezas_pedidos)
    para el campo "Id de pedido de stock" del Libro de Compras. */
export function BuscarPedidoStockDialog({
  open,
  onOpenChange,
  onSeleccionar,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSeleccionar: (pedido: PedidoStockBusqueda) => void;
}) {
  const [busqueda, setBusqueda] = useState("");
  const [pedidos, setPedidos] = useState<PedidoStockBusqueda[]>([]);
  const [cargando, setCargando] = useState(false);

  useEffect(() => {
    if (!open) setBusqueda("");
  }, [open]);

  useEffect(() => {
    if (!open) return;
    setCargando(true);
    const timer = setTimeout(() => {
      const p = new URLSearchParams();
      if (busqueda.trim()) p.set("q", busqueda.trim());
      fetch(`/api/stock-piezas/pedidos/buscar?${p.toString()}`)
        .then((r) => r.json())
        .then((d) => { if (d.ok) setPedidos(d.pedidos); })
        .finally(() => setCargando(false));
    }, busqueda.trim() ? 300 : 0);
    return () => clearTimeout(timer);
  }, [open, busqueda]);

  function seleccionar(p: PedidoStockBusqueda) {
    onSeleccionar(p);
    onOpenChange(false);
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="flex max-h-[85vh] flex-col gap-3 sm:max-w-2xl">
        <DialogHeader>
          <DialogTitle>Buscar pedido de stock</DialogTitle>
        </DialogHeader>

        <div className="relative">
          <SearchNormal1 className="pointer-events-none absolute left-2.5 top-1/2 size-3.5 -translate-y-1/2 text-muted-foreground" />

