      <Button
        type="button"
        variant="ghost"
        size="icon-sm"
        className="text-primary-foreground hover:bg-primary-foreground/15 hover:text-primary-foreground"
        onClick={nuevoCodigo}
        disabled={generando}
        title="Generar nuevo código de acceso"
