export function ClienteSeLoLlevoDialog({
  resguardo,
  open,
  onOpenChange,
  onConfirmado,
}: {
  resguardo: string;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onConfirmado: () => void;
}) {
