    const data = await res.json();
    if (!data.ok) throw new Error(data.error || "Error desconocido");
    toast.success("Equipo marcado como recogido por el cliente");
    onOpenChange(false);
    onConfirmado();
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error desconocido");
  } finally {
    setEnviando(false);
  }
}

