/**
 * Número de la factura principal de reparación, más — el original nunca lo
 * hacía (`Index.html:13273-13294` solo mostraba rep.numeroFactura) — el
 * anticipo y la de mensajería si existen, ya que quedaban sin ninguna
 * referencia visible en esta ficha una vez generadas.
 */
function EstadoFactura({ detalle }: { detalle: ReparacionDetalle }) {
  const extras: ReactNode[] = [];
  if (detalle.numeroFacturaAnticipo) {
    extras.push(<BadgeFactura key="anticipo" numero={detalle.numeroFacturaAnticipo} url={detalle.urlFacturaAnticipo} etiqueta="Anticipo" />);
  } else if (detalle.numeroTicketAnticipo) {
    extras.push(<BadgeTicket key="anticipo" numero={detalle.numeroTicketAnticipo} url={detalle.urlTicketAnticipo} etiqueta="Anticipo" />);
  }
  if (detalle.numeroFacturaMensajeria) {
    extras.push(<BadgeFactura key="mensajeria" numero={detalle.numeroFacturaMensajeria} url={detalle.urlFacturaMensajeria} etiqueta="Mensajería" />);
  } else if (detalle.numeroTicketMensajeria) {
    // Mismo caso que el ticket de anticipo arriba — el ticket de
    // mensajería es la alternativa al elegir "Ticket" en vez de "Factura"
    // en "Facturar y Enviar por Mensajería"/"Entregado en Local"/"Enviar a
    // Punto Limpio". Bug real reportado, 2026-08-27: la ficha seguía
    // mostrando "—" en Factura pese a tener el ticket ya generado.
    extras.push(<BadgeTicket key="mensajeria" numero={detalle.numeroTicketMensajeria} url={detalle.urlTicketMensajeria} etiqueta="Mensajería" />);
  }

  if (detalle.numeroFactura) {
    return (
      <div className="flex flex-wrap items-center gap-1.5">
        <BadgeFactura numero={detalle.numeroFactura} url={detalle.urlFactura} />
        {extras}
      </div>
    );
  }

  // Un Ticket Rápido cumple el mismo papel que la factura de reparación

  // (la resuelve como documento de cobro) cuando se eligió esa vía en vez
  // de facturación real — sin esto, la ficha seguía mostrando "Pendiente"
  // aunque el ticket ya estuviera generado. Bug real reportado por el
  // usuario, 2026-08-27.
  if (detalle.numeroTicket) {
    return (
      <div className="flex flex-wrap items-center gap-1.5">
        <BadgeTicket numero={detalle.numeroTicket} url={detalle.urlTicket} />
        {extras}
      </div>
    );
  }

  const requiereFactura =
    detalle.tipoIngreso !== "GARANTIA" &&
    (detalle.estado === "Reparado" || detalle.estado === "Presupuesto Aceptado");

  if (!requiereFactura && extras.length === 0) return <span className="text-muted-foreground">—</span>;

  return (
    <div className="flex flex-wrap items-center gap-1.5">
      {requiereFactura && (
        <span className="inline-flex items-center gap-1 rounded-md bg-amber-400 px-2 py-0.5 text-xs font-medium text-amber-950">
          <Warning2 className="size-3.5" /> Pendiente
        </span>
      )}
      {extras}
    </div>
  );
}

/** Plataforma real de compra, a partir del dominio del enlace — el
    desplegable "Proveedor" del formulario mezcla plataformas (Amazon,
    AliExpress, eBay) con fabricantes (Asus, Lenovo, MSI...), así que
    quien registra el pedido a veces elige la marca de la pieza en vez
    de dónde se compró (ej. una pantalla MSI comprada en Amazon, con
    "MSI" seleccionado). El enlace es la fuente más fiable de "dónde" —
    se prioriza sobre el proveedor elegido cuando coincide con una
    plataforma conocida. */
const PLATAFORMAS_POR_DOMINIO: { patron: RegExp; nombre: string }[] = [
  { patron: /(^|\.)amazon\./i, nombre: "Amazon" },
  { patron: /(^|\.)aliexpress\./i, nombre: "AliExpress" },
  { patron: /(^|\.)ebay\./i, nombre: "eBay" },
  { patron: /(^|\.)mercadolibre\.|(^|\.)mercadolivre\./i, nombre: "MercadoLibre" },
  { patron: /(^|\.)pccomponentes\./i, nombre: "PcComponentes" },
  { patron: /(^|\.)wallapop\./i, nombre: "Wallapop" },
];

function plataformaDesdeEnlace(enlace: string): string | null {
  if (!enlace) return null;
  try {
    const host = new URL(enlace).hostname;

    return PLATAFORMAS_POR_DOMINIO.find((p) => p.patron.test(host))?.nombre ?? null;
  } catch {
    return null;
  }
}

