async function imprimirEtiqueta() {
  if (!resguardo || imprimiendoEtiqueta) return;
  setImprimiendoEtiqueta(true);
  try {
    const ok = await imprimirEtiquetaResguardoConFeedback(resguardo);
    if (ok) {
      toast.success("Etiqueta enviada a la impresora");
      actualizarTodo();
    } else {
      toast.error("No se pudo imprimir — comprueba que el puente de impresión esté corriendo en este PC");
    }
  } finally {
    setImprimiendoEtiqueta(false);
  }
}

async function imprimirResguardo() {
  if (!resguardo || imprimiendoResguardo) return;
  setImprimiendoResguardo(true);
  try {
    const res = await fetch(`/api/reparaciones/${resguardo}/resguardo-html`);
    const data = await res.json();

    if (!data.ok) throw new Error(data.error || "No se pudo generar el resguardo");
    const ventana = window.open("", "_blank");
    if (!ventana) throw new Error("El navegador bloqueó la ventana de impresión");
    ventana.document.write(data.html);
    ventana.document.close();
    ventana.onload = () => ventana.print();
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error desconocido");
  } finally {
    setImprimiendoResguardo(false);
  }
}

function cargarDetalle() {
  if (!resguardo) return;
  fetch(`/api/reparaciones/${resguardo}`)
    .then((r) => r.json())
    .then((data) => {
      if (!data.ok) throw new Error(data.error);
      setDetalle(data.detalle as ReparacionDetalle);
    })
    .catch((e) => setError(e instanceof Error ? e.message : "Error desconocido"));
}

