 * estado a "En Reparación" (o a "Presupuesto Pendiente"/"Pieza Pendiente"
 * si el backend detecta que aún faltan pedidos, ver el 409 de
 * /flujo-inicial). Mismo endpoint que marcarComoGarantia
 * (accion:"iniciar_reparacion" en vez de "marcar_garantia").
 */
export function IniciarReparacionDialog({
  resguardo,
  open,
  onOpenChange,
  onIniciado,
}: {
  resguardo: string;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onIniciado: () => void;
}) {
  const [tecnico, setTecnico] = useState("");
  const [observacion, setObservacion] = useState("");
  const [enviando, setEnviando] = useState(false);

  useEffect(() => {
    if (!open) return;
    usuarioIdentificadoComoTecnico(TECNICOS).then((nombre) => { if (nombre) setTecnico(nombre); });
  }, [open]);

  function cerrar(o: boolean) {
    if (enviando) return;
    if (!o) { setTecnico(""); setObservacion(""); }
    onOpenChange(o);
  }

  async function confirmar() {
    if (!tecnico) return toast.error("Debe seleccionar un técnico responsable");
    setEnviando(true);
    try {
      const res = await fetch(`/api/reparaciones/${resguardo}/flujo-inicial`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },

      body: JSON.stringify({ accion: "iniciar_reparacion", datos: { tecnico, observacion: observacion.trim() } }),
    });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || "Error desconocido");
    toast.success(`Reparación iniciada. Técnico: ${tecnico}`);
    setTecnico("");
    setObservacion("");
    onOpenChange(false);
    onIniciado();
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error desconocido");
  } finally {
    setEnviando(false);
  }
}

return (
  <Dialog open={open} onOpenChange={cerrar}>
    <DialogContent className="gap-0 p-0 sm:max-w-md" showCloseButton={false}>
      <header className="flex items-center gap-2 rounded-t-xl bg-emerald-600 px-4 py-3 text-white">
        <Setting2 className="size-4.5 shrink-0" />
        <DialogTitle className="text-sm font-semibold text-white">Iniciar Reparación</DialogTitle>
        <Button variant="ghost" size="icon-sm" className="ml-auto text-white hover:bg-white/15 hover:text-white" onClick={() => cerrar(false)} disabled={enviando}>
          <CloseCircle className="size-4" />
        </Button>
      </header>

      <div className="space-y-3 p-4">
        <p className="text-sm text-muted-foreground">Asigne el técnico responsable de realizar la reparación.</p>

        <div className="space-y-1.5">
          <Label>Técnico Responsable *</Label>
          <Select value={tecnico} onValueChange={(v) => setTecnico(v || "")}>
            <SelectTrigger className="w-full"><SelectValue placeholder="Seleccione un técnico..." /></SelectTrigger>
            <SelectContent>
              {TECNICOS.map((t) => <SelectItem key={t} value={t}>{t}</SelectItem>)}
            </SelectContent>
          </Select>
        </div>
        <div className="space-y-1.5">
          <Label>Observaciones (opcional)</Label>
          <Textarea rows={2} placeholder="Notas adicionales..." value={observacion} onChange={(e) => setObservacion(e.target.value)} />
        </div>
      </div>

      <footer className="flex justify-end gap-2 border-t bg-muted/50 px-4 py-3">

"use client";

import { useState } from "react";
import { Truck, Shop, Home, Lock } from "@/lib/icons";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import { ReparacionDetalle } from "@/lib/reparacion-detalle";

// Mismos estados que actualizarSeccionEquipoEnLocal() en Index.html — el
// toggle "equipo en local" solo tiene sentido mientras se espera una pieza.
const ESTADOS_CON_TOGGLE_EQUIPO = ["Pieza Pendiente", "En Tránsito", "Pieza Entregada"];

export function LogisticaPanel({
  detalle,
  onActualizado,
  onClienteSeLleva,
  onClienteSeLlevaDirecto,
  onClienteLoTrajo,
  bloqueado = false,
}: {
  detalle: ReparacionDetalle;
  onActualizado: () => void;
  /** Reproduce toggleEquipoEnLocal(): "Cliente se lleva" NO cambia el
   * estado directamente — abre la factura de anticipo (50%) antes, y es
   * esa confirmación la que deja el equipo en 'NO'. */
  onClienteSeLleva: () => void;
  /** Sin presupuesto de por medio (Garantía: reparación gratuita) no hay
      nada sobre lo que calcular un anticipo del 50% — confirmación simple
      + toggle directo, igual que onClienteLoTrajo. */
  onClienteSeLlevaDirecto: () => void;
  /** Dirección inversa: confirmación simple + toggle directo (marcarEquipoRecibido). */
  onClienteLoTrajo: () => void;
  /** Reparación entregada y facturada: cambiar la entrega por mensajería o
      si el equipo está en local ya no debería alterar lo que la factura
      emitida refleja (mismo criterio que ClienteEditable/EquipoEditable). */
  bloqueado?: boolean;
}) {
  const [direccion, setDireccion] = useState(detalle.cliente.direccion || "");
  const [enviando, setEnviando] = useState(false);
  const mensajeriaActiva = detalle.entregaMensajeria === "SI";
  const equipoEnLocal = detalle.equipoEnLocal !== "NO";
  const mostrarToggleEquipo = ESTADOS_CON_TOGGLE_EQUIPO.includes(detalle.estado);
  // Típico de Garantía: reparación gratuita, sin presupuesto que aceptar —
  // exigir un anticipo del 50% de "nada" solo bloqueaba el toggle sin
  // dejar ninguna forma de marcar "Cliente se lleva" (bug real reportado).

const sinPresupuesto = detalle.presupuestos.length === 0;

async function ejecutar(accion: string, datos: Record<string, unknown>) {
  setEnviando(true);
  try {
    const res = await fetch(`/api/reparaciones/${detalle.resguardo}/logistica`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ accion, datos }),
    });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || "Error desconocido");
    toast.success("Actualizado");
    onActualizado();
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error desconocido");
  } finally {
    setEnviando(false);
  }
}

return (
  <div className="space-y-3">
    {/* Tira a lo ancho con el texto a la izquierda y el botón al final,
        como la sección de mensajería del sistema original. */}
    <div
      className={`flex flex-wrap items-center gap-3 rounded-xl border p-3 ${
        mensajeriaActiva ? "border-amber-500/40 bg-amber-500/10" : "bg-muted/40"
      }`}
    >
      <Truck className="size-5 shrink-0 text-muted-foreground" variant="Bold" />
      <div className="min-w-40 flex-1">
        <p className="text-sm font-medium">Entrega por mensajería</p>
        <p className="text-xs text-muted-foreground">
          {mensajeriaActiva
            ? detalle.cliente.direccion || "Sin dirección especificada"
            : "Actívala si el cliente solicita envío a domicilio"}
        </p>
      </div>
      {bloqueado ? (
        <span className="flex items-center gap-1 text-xs text-muted-foreground" title="Reparación entregada y facturada: no se puede cambiar la entrega por mensajería">
          <Lock className="size-3.5" />
        </span>
      ) : mensajeriaActiva ? (
        <Button
          size="sm"
          variant="outline"
          disabled={enviando}
          onClick={() => ejecutar("entrega_mensajeria", { activar: "NO", direccion: "" })}
        >
          Desactivar
        </Button>
      ) : (
        <>
          <Input
            placeholder="Dirección de envío"

              value={direccion}
              onChange={(e) => setDireccion(e.target.value)}
              className="h-8 w-full text-xs sm:w-64"
            />
            <Button
              size="sm"
              className="bg-amber-500 text-white hover:bg-amber-600"
              disabled={enviando}
              onClick={() => ejecutar("entrega_mensajeria", { activar: "SI", direccion })}
            >
              Activar
            </Button>
          </>
        )}
      </div>

      {mostrarToggleEquipo && !bloqueado && (
        <div
          className={`flex flex-wrap items-center gap-3 rounded-xl border p-3 ${
            equipoEnLocal ? "border-emerald-500/40 bg-emerald-500/10" : "border-amber-500/40 bg-amber-500/10"
          }`}
        >
          {equipoEnLocal ? (
            <Shop className="size-5 shrink-0 text-muted-foreground" variant="Bold" />
          ) : (
            <Home className="size-5 shrink-0 text-muted-foreground" variant="Bold" />
          )}
          <div className="min-w-40 flex-1">
            <p className="text-sm font-medium">
              {equipoEnLocal ? "Equipo en local" : "Cliente se llevó el equipo"}
            </p>
            <p className="text-xs text-muted-foreground">
              {equipoEnLocal ? "Disponible en el local para reparación" : "Debe traerlo de nuevo para continuar"}
            </p>
          </div>
          <Button
            size="sm"
            variant={equipoEnLocal ? "outline" : "default"}
            disabled={enviando}
            onClick={equipoEnLocal ? (sinPresupuesto ? onClienteSeLlevaDirecto : onClienteSeLleva) : onClienteLoTrajo}
          >
            {equipoEnLocal ? "Cliente se lleva" : "Cliente lo trajo"}
          </Button>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { ShieldTick } from "@/lib/icons";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import { useConfirm } from "@/components/confirm-provider";
import { ReparacionDetalle } from "@/lib/reparacion-detalle";

export const ENTREGA_CERRADA = ["ENTREGADO", "ENVIO", "RECICLAJE"];

/**
 * Reproduce el botón "Marcar Garantía" de la fila "Estado Actual" del
 * original (btnMarcarGarantia) — visible salvo que ya sea garantía o la
 * entrega ya esté cerrada, igual que su lógica de visibilidad.
 */
export function MarcarGarantiaBoton({
  detalle,
  onActualizado,
}: {
  detalle: ReparacionDetalle;
  onActualizado: () => void;
}) {
  const [enviando, setEnviando] = useState(false);
  const confirmar = useConfirm();

  const yaEsGarantia = detalle.tipoIngreso === "GARANTIA";
  const entregada = ENTREGA_CERRADA.includes(detalle.estadoEntrega);
  if (yaEsGarantia || entregada) return null;

  async function marcar() {
    const ok = await confirmar("¿Marcar esta reparación como Garantía?\n\nLa factura pasará a ser opcional al momento de la entrega.");
    if (!ok) return;
    setEnviando(true);
    try {
      const res = await fetch(`/api/reparaciones/${detalle.resguardo}/flujo-inicial`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ accion: "marcar_garantia" }),
      });
      const data = await res.json();
      if (!data.ok) throw new Error(data.error || "Error desconocido");
      toast.success("Reparación marcada como garantía");
      onActualizado();
    } catch (e) {
      toast.error(e instanceof Error ? e.message : "Error desconocido");
    } finally {
      setEnviando(false);
    }
  }

  return (
    <Button size="sm" variant="outline" className="gap-1.5" disabled={enviando} onClick={marcar}>
      <ShieldTick className="size-3.5" /> Marcar Garantía
    </Button>
  );
}

