/**
 * Reproduce abrirVistaFacturaManual()/generarPdfFactura() (modo 'manual')
 * del original — botón verde junto a "Nueva Reparación" en Todas las
 * Reparaciones (#modalVistaFactura reutilizado, sin las cards de Equipo/
 * Servicio ni Reseña, ocultas en este modo). Mismo diseño de modal que
 * FaseCorregida (factura-acciones-tabs.tsx). Simplificación deliberada
 * frente al original: el cliente aquí es directamente editable + botón
 * "Buscar" (igual que el resto del puerto), en vez del autocompletado
 * por DNI mientras escribes.
 */
export function NuevaFacturaManualDialog({
  open,
  onOpenChange,
  onGenerada,
  lineaInicial,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onGenerada: () => void;
  /** Precarga una única línea al abrir (p. ej. al escanear el código de
      barras de una pieza de Stock, como un cargador). */
  lineaInicial?: { referencia: string; descripcion: string; precio: number };
}) {
  const [serie, setSerie] = useState<"1" | "3">("1");
  const [nombre, setNombre] = useState("");
  const [direccion, setDireccion] = useState("");
  const [dni, setDni] = useState("");
  const [telefono, setTelefono] = useState("");
  const [email, setEmail] = useState("");
  const [buscarClienteAbierto, setBuscarClienteAbierto] = useState(false);

const [buscarStockAbierto, setBuscarStockAbierto] = useState(false);
const [pago, setPago] = useState<ValorFormaPago>(valorFormaPagoVacio());
const [estadoFactura, setEstadoFactura] = useState("Cobrada");
const [suReferencia, setSuReferencia] = useState("");
const [lineas, setLineas] = useState<LineaFactura[]>([{ descripcion: "", cantidad: 1, precio: 0 }]);
// Igual que factura-reparacion-dialog.tsx: solo afecta a la vista previa
// en pantalla, se materializa como una línea negativa propia al generar
// (ver generar()) para que quede reflejado en el PDF y en el total real,
// en vez de perderse silenciosamente.
const [descuentoGlobalPct, setDescuentoGlobalPct] = useState(0);
const [enviando, setEnviando] = useState(false);
const [requestId, setRequestId] = useState<string | null>(null);
const [resultado, setResultado] = useState<{ numeroFactura: string; urlPdf: string; entidadId: string } | null>(null);
const [enviandoFactura, setEnviandoFactura] = useState(false);
const confirmar = useConfirm();

useEffect(() => {
  if (open && lineaInicial) {
    setLineas([{ referencia: lineaInicial.referencia, descripcion: lineaInicial.descripcion, cantidad: 1, precio: lineaInicial.precio }]);
  }
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [open]);

const subtotal = lineas.reduce((s, l) => s + l.cantidad * l.precio * (1 - (l.descuento || 0) / 100), 0);
const pctGlobal = Math.min(100, Math.max(0, descuentoGlobalPct || 0));
const descuentoAmt = (subtotal * pctGlobal) / 100;
const base = subtotal - descuentoAmt;
const iva = base * IVA_PCT;
const totalConIva = base + iva;

function actualizarLinea(i: number, campo: keyof LineaFactura, valor: string | number) {
  setLineas((prev) => prev.map((l, idx) => (idx === i ? { ...l, [campo]: valor } : l)));
}

/** Reproduce _vfSeleccionarArticulo() (Index.html): añade una línea nueva
    precargada con los datos del artículo elegido en el catálogo de Stock
    de Piezas, en vez de tener que escribirlos a mano. */
function agregarLineaDesdeStock(p: StockPieza) {
  setLineas((prev) => {

    const nuevas = [...prev, { referencia: p.referencia, descripcion: p.descripcion || p.nombre, cantidad: 1, precio: p.precioCliente }];
    // La pieza puede llevar su propia mano de obra asociada — al no
    // haber una casilla de "Mano de Obra" en la factura (a diferencia
    // del presupuesto), se añade como línea propia para que quede
    // reflejada en el total.
    if (p.manoObra > 0) {
      nuevas.push({ descripcion: `Mano de obra — ${p.descripcion || p.nombre}`, cantidad: 1, precio: p.manoObra });
    }
    return nuevas;
  });
  setBuscarStockAbierto(false);
}

function seleccionarCliente(c: Cliente) {
  setNombre(c.nombre || "");
  setDireccion(c.direccion || "");
  setDni(c.dniCif || "");
  setTelefono(c.telefono || "");
  setEmail(c.email || "");
  toast.success("Cliente cargado");
}

function reiniciar() {
  setSerie("1"); setNombre(""); setDireccion(""); setDni(""); setTelefono(""); setEmail("");
  setPago(valorFormaPagoVacio()); setEstadoFactura("Cobrada");
  setLineas([{ descripcion: "", cantidad: 1, precio: 0 }]);
  setDescuentoGlobalPct(0);
  setRequestId(null); setResultado(null);
}

function cerrar(o: boolean) {
  if (enviando) return;
  if (!o) reiniciar();
  onOpenChange(o);
}

async function generar() {
  const validas = lineas.filter((l) => l.descripcion.trim() || l.precio);
  if (validas.length === 0) return toast.error("Añade al menos un concepto");
  if (!nombre.trim()) return toast.error("El nombre del cliente es obligatorio");
  const errorPago = validarFormaPago(pago, totalConIva);
  if (errorPago) return toast.error(errorPago);

  setEnviando(true);
  const rid = requestId || crypto.randomUUID();
  setRequestId(rid);
  try {
    const importeGlobal = Math.round(descuentoAmt * 100) / 100;
    const lineasConDescuento = pctGlobal > 0 && importeGlobal > 0
      ? [...validas, { descripcion: `Descuento global (${pctGlobal}%)`, cantidad: 1, precio: -importeGlobal }]
      : validas;
    const res = await fetch("/api/facturas-manuales", {
      method: "POST",
      headers: { "Content-Type": "application/json" },

      body: JSON.stringify({
        requestId: rid,
        serie,
        cliente: { nombre: nombre.trim(), direccion: direccion.trim(), dni: dni.trim(), telefono: telefono.trim(), email: email.trim() },
        ...formaPagoParaPayload(pago),
        estadoFactura,
        lineas: lineasConDescuento,
      }),
    });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || "Error desconocido");
    toast.success(`Factura ${data.numeroFactura} generada correctamente`);
    guardarSuReferencia(data.numeroFactura, suReferencia);
    setResultado({ numeroFactura: data.numeroFactura, urlPdf: data.urlPdf, entidadId: data.entidadId });
    onGenerada();
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error desconocido");
  } finally {
    setEnviando(false);
  }
}

// Botón siempre visible, deshabilitado hasta que exista la factura y haya
// un correo de destino — mismo patrón que Ticket Manual (ticket-manual-
// dialog.tsx), petición del usuario 2026-09-02.
const puedeEnviar = !!resultado && !!email.trim();

async function enviarFactura() {
  if (!resultado) return;
  const destino = email.trim();
  if (!destino) return toast.error("No hay ningún correo de destino disponible");
  const ok = await confirmar(`¿Enviar la factura ${resultado.numeroFactura} a ${destino}?`);
  if (!ok) return;

  setEnviandoFactura(true);
  try {
    const res = await fetch(`/api/facturas-manuales/${resultado.entidadId}/enviar`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ tipo: "manual", emailDestino: destino }),
    });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || "Error desconocido");
    if (!data.enviado) throw new Error(data.motivo || "No se pudo enviar");
    toast.success(`Factura enviada a ${destino}`);
  } catch (e) {
    toast.error(e instanceof Error ? e.message : "Error desconocido");
  } finally {
    setEnviandoFactura(false);
  }
}

return (
  <Dialog open={open} onOpenChange={cerrar}>

"use client";

import Link from "next/link";
import { Suspense, useEffect, useMemo, useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { Refresh2, Filter, ArrowDown2, Eye, ClipboardTick, CloseCircle, AddCircle, SearchNormal1, Calendar, Receipt, Trash, Ticket, Copy, Wallet } from "@/lib/icons";
import { toast } from "sonner";
