interface FilaRegistroSql {
  id: number;
  fecha: string;
  usuario: string | null;
  proveedor_nombre: string | null;
  numero_pedido_global: string | null;
  pedidos_stock: number;
  pedidos_resguardo: number;
  lineas_fallidas: number;
  resumen: LineaRegistroPedidoProveedor[];
}

export interface RegistroPedidoProveedor {
  id: number;
  fecha: string;
  usuario: string;
  proveedorNombre: string;
  numeroPedidoGlobal: string | null;
  pedidosStock: number;
  pedidosResguardo: number;
  lineasFallidas: number;
  resumen: LineaRegistroPedidoProveedor[];
}

function mapear(f: FilaRegistroSql): RegistroPedidoProveedor {
  return {
    id: f.id,
    fecha: f.fecha,
    usuario: f.usuario || "",
    proveedorNombre: f.proveedor_nombre || "",
    numeroPedidoGlobal: f.numero_pedido_global,
    pedidosStock: f.pedidos_stock,
    pedidosResguardo: f.pedidos_resguardo,
    lineasFallidas: f.lineas_fallidas,
    resumen: Array.isArray(f.resumen) ? f.resumen : [],
  };
}

/** Proxy de GET /v1/compras/pedido-proveedor/registros — para el botón
    "Historial" junto a "Subir pedido con IA": qué se ha registrado con
    esa función, más reciente primero. */
export async function GET() {
  try {
    const data = await kelatosApiGet<{ ok: boolean; registros: FilaRegistroSql[] }>("/v1/compras/pedido-proveedor/registros", { limite: 30 });
    return NextResponse.json({ ok: true, registros: data.registros.map(mapear) });
  } catch (error) {
    return NextResponse.json({ ok: false, error: error instanceof Error ? error.message : "Error desconocido" }, { status: 502 });
  }
}

import { NextResponse } from "next/server";
import { auth } from "@/auth";
import { kelatosApiPost } from "@/lib/kelatos-api";
import { esCuentaEmpleadosRestringida } from "@/lib/superadmin";

/** Una línea de pedido leída del pantallazo (p. ej. plataforma de ASWO),
    ya clasificada en "tienda" (pieza para Stock de Piezas) o "cliente"
    (pieza para la reparación del nombre detectado en "Texto del pedido") y,
    si es "tienda", emparejada por nombre contra el catálogo de Stock de
    Piezas — igual que ArticuloFacturaEmparejado en facturas-recibidas/ocr. */
export interface LineaPedidoProveedorLeida {
  nombre: string;
  /** Código/ID del artículo visto junto al nombre en el pantallazo (si lo
      hay) — se usa para reconocer una pieza ya existente con más
      fiabilidad que comparando solo nombres. */
  codigoProveedor: string | null;
  /** Código corto que aparece junto/debajo al nombre del artículo en el
      pantallazo (p. ej. "#R696190" en ASWO) — distinto del código de
      fabricante, otra seña exacta para el emparejamiento. */
  idPedidoProveedor: string | null;
  cantidad: number;
  precioUnitario: number | null;
  /** Texto crudo leído bajo "Texto del pedido" — se muestra en la revisión
      para que el empleado vea por qué se clasificó así. */
  textoPedido: string;
  destino: "tienda" | "cliente";
  /** Solo relevante cuando destino === "tienda". */
  referenciaSugerida: string | null;
  nombrePiezaSugerida: string | null;
  categoriaSugerida: string | null;
  precioClienteSugerido: number | null;
}

const MAX_ARCHIVOS_PEDIDO = 4;
const TIPOS_PEDIDO_VALIDOS = new Set(["image/jpeg", "image/jpg", "image/png", "image/webp", "application/pdf"]);

/** Proxy de POST /v1/compras/pedido-proveedor/ocr — lectura automática de
    un pantallazo de pedido hecho en la web de un proveedor. No persiste
    nada, solo devuelve las líneas leídas para que el empleado las revise y
    confirme antes de registrar ningún pedido de verdad. */
export async function POST(req: Request) {
  const session = await auth();
  if (esCuentaEmpleadosRestringida(session?.user?.email)) return NextResponse.json({ ok: false, error: "No autorizado" }, { status: 403 });

  const body = (await req.json().catch(() => ({}))) as {
    base64?: string;
    mimeType?: string;
    nombreProveedor?: string;
    /** Formato nuevo: de 1 a 4 archivos (imágenes y/o PDF) en un solo análisis. */
    archivos?: { base64?: string; mimeType?: string }[];
  };
  // Compatibilidad: un solo archivo con el formato antiguo se trata como lista de 1.
  const archivos = (Array.isArray(body.archivos) ? body.archivos : body.base64 ? [{ base64: body.base64, mimeType: body.mimeType }] : [])
    .filter((a): a is { base64: string; mimeType: string } => !!a && typeof a.base64 === "string" && !!a.base64 && typeof a.mimeType === "string" && !!a.mimeType);
  if (archivos.length === 0) return NextResponse.json({ ok: false, error: "Faltan datos del archivo" }, { status: 400 });
  if (archivos.length > MAX_ARCHIVOS_PEDIDO) return NextResponse.json({ ok: false, error: `Máximo ${MAX_ARCHIVOS_PEDIDO} archivos por análisis` }, { status: 400 });
  if (archivos.some((a) => !TIPOS_PEDIDO_VALIDOS.has(a.mimeType))) return NextResponse.json({ ok: false, error: "Solo se admiten imágenes (JPG, PNG, WEBP) o PDF" }, { status: 400 });

  try {
    // La IA es lenta y el proxy corta a los 60 s: el análisis corre en segundo plano en el servidor y
    // aquí solo se devuelve el identificador; el resultado se consulta en GET /ocr/[jobId].
    const data = await kelatosApiPost<{ ok: boolean; jobId: string }>("/v1/compras/pedido-proveedor/ocr", {
      archivos,
      nombreProveedor: body.nombreProveedor || undefined,
      async: true,
    });
    return NextResponse.json({ ok: true, jobId: data.jobId });
  } catch (error) {
    return NextResponse.json({ ok: false, error: error instanceof Error ? error.message : "No se pudo leer el pedido" }, { status: 502 });
  }
}

import { NextResponse } from "next/server";
import { auth } from "@/auth";
import { kelatosApiGet } from "@/lib/kelatos-api";
import { esCuentaEmpleadosRestringida } from "@/lib/superadmin";
import type { LineaPedidoProveedorLeida } from "../route";

export const dynamic = "force-dynamic";

/** Consulta el estado de un análisis de pedido que corre en segundo plano
    (ver POST /api/compras/pedido-proveedor/ocr). "procesando" mientras la IA
    trabaja; "listo" con las líneas leídas; "error" con el motivo. */
export async function GET(_req: Request, { params }: { params: Promise<{ jobId: string }> }) {
  const session = await auth();
  if (!session?.user?.email) return NextResponse.json({ ok: false, error: "No autenticado" }, { status: 401 });
  if (esCuentaEmpleadosRestringida(session.user.email)) return NextResponse.json({ ok: false, error: "No autorizado" }, { status: 403 });

  const { jobId } = await params;
  if (!/^[A-Za-z0-9-]{8,64}$/.test(jobId)) return NextResponse.json({ ok: false, error: "Identificador no válido" }, { status: 400 });

  try {
    const data = await kelatosApiGet<{
      ok: boolean;
      estado: "procesando" | "listo" | "error";
      segundos?: number;
      error?: string;
      numeroPedidoGlobal?: string | null;
      lineas?: LineaPedidoProveedorLeida[];
      proveedorIdSugerido?: string | null;
      proveedorCreado?: boolean;
    }>(`/v1/compras/pedido-proveedor/ocr/${encodeURIComponent(jobId)}`);

    if (data.estado === "listo") {
      return NextResponse.json({
        ok: true,
        estado: "listo",
        numeroPedidoGlobal: data.numeroPedidoGlobal ?? null,
        lineas: data.lineas || [],
        proveedorIdSugerido: data.proveedorIdSugerido ?? null,
        proveedorCreado: !!data.proveedorCreado,
      });
    }
    if (data.estado === "error") return NextResponse.json({ ok: true, estado: "error", error: data.error || "No se pudo leer el pedido" });
    return NextResponse.json({ ok: true, estado: "procesando", segundos: data.segundos ?? 0 });
  } catch (error) {
    return NextResponse.json({ ok: false, error: error instanceof Error ? error.message : "No se pudo consultar el análisis" }, { status: 502 });

import { NextResponse } from "next/server";
import { auth } from "@/auth";
import { kelatosApiPost } from "@/lib/kelatos-api";

/** Línea de resumen de lo que se aplicó al pulsar "Registrar pedidos" en
    el diálogo de pantallazo — deliberadamente breve (nombre, cantidad,
    destino) para el botón "Historial". */
export interface LineaRegistroPedidoProveedor {
  nombre: string;
  cantidad: number;
  destino: "tienda" | "cliente";
  destinoDetalle: string;
  ok: boolean;
}

/** Proxy de POST /v1/compras/pedido-proveedor/registro — deja constancia
    de una pasada de "Registrar pedidos" ya completada (nunca bloquea ni
    valida, se llama después de que los pedidos reales ya se crearon). */
export async function POST(req: Request) {
  const session = await auth();
  const usuario = session?.user?.email || "";

  const body = (await req.json().catch(() => ({}))) as {
    proveedorNombre?: string;
    numeroPedidoGlobal?: string | null;
    pedidosStock?: number;
    pedidosResguardo?: number;
    lineasFallidas?: number;
    resumen?: LineaRegistroPedidoProveedor[];
  };

  try {
    await kelatosApiPost("/v1/compras/pedido-proveedor/registro", {
      usuario,
      proveedorNombre: body.proveedorNombre || "",
      numeroPedidoGlobal: body.numeroPedidoGlobal || null,
      pedidosStock: body.pedidosStock || 0,
      pedidosResguardo: body.pedidosResguardo || 0,
      lineasFallidas: body.lineasFallidas || 0,
      resumen: body.resumen || [],
    });
    return NextResponse.json({ ok: true });
  } catch (error) {
    // No es crítico — si falla el registro del historial no debe parecer
    // que falló el propio "Registrar pedidos" (que ya se completó antes).
    return NextResponse.json({ ok: false, error: error instanceof Error ? error.message : "Error desconocido" }, { status: 502 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { kelatosApiGet } from "@/lib/kelatos-api";
import { CompraFila, KpisCompras, mapearCompra } from "@/lib/compras";

interface RespuestaCompras {
  ok: boolean;
  total: number;
  kpis: KpisCompras;
  compras: Parameters<typeof mapearCompra>[0][];
}

/** Proxy de GET /v1/compras — todos los pedidos de piezas de todas las reparaciones. */
export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);

  try {
    const data = await kelatosApiGet<RespuestaCompras>("/v1/compras", {
      estado: searchParams.get("estado") ?? undefined,
      retrasado: searchParams.get("retrasado") ?? undefined,
      proveedorId: searchParams.get("proveedorId") ?? undefined,
      compradoPor: searchParams.get("compradoPor") ?? undefined,
      busqueda: searchParams.get("busqueda") ?? undefined,
      fechaDesde: searchParams.get("fechaDesde") ?? undefined,
      fechaHasta: searchParams.get("fechaHasta") ?? undefined,
      orden: searchParams.get("orden") ?? undefined,
      pagina: searchParams.get("pagina") ?? "1",
      porPagina: searchParams.get("porPagina") ?? "50",
    });

    const compras: CompraFila[] = data.compras.map(mapearCompra);
    return NextResponse.json({ ok: true, compras, total: data.total, kpis: data.kpis });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Error desconocido";
    return NextResponse.json({ ok: false, error: message }, { status: 502 });
  }
}

import { NextResponse } from "next/server";
import { createHmac } from "node:crypto";
import { auth } from "@/auth";
import { esSuperadmin, puedeVerEfectivoSoloLectura } from "@/lib/superadmin";
import { origenPropio } from "@/lib/publico-seguridad";

export const dynamic = "force-dynamic";

const BASE_URL = process.env.KELATOS_API_BASE_URL;
const TOKEN = process.env.KELATOS_API_TOKEN;

/**
 * Proxy único hacia /v1/contabilidad/* del backend. La identidad NUNCA viene
 * del navegador: se toma de la sesión en el servidor y se inyecta como
 * `usuario`. Si CONTABILIDAD_FIRMA_SECRET está definida (aquí y en el VPS),
 * además se firma con HMAC para que el token compartido por sí solo no permita
 * actuar como administrador.
 */
async function manejar(req: Request, ctx: { params: Promise<{ ruta: string[] }> }) {
  const session = await auth();
  const email = session?.user?.email?.toLowerCase();
  if (!email) {
    return NextResponse.json({ ok: false, error: "Solo los administradores pueden acceder a Contabilidad" }, { status: 403 });
  }
  const esAdminCompleto = session?.user?.role === "admin" || esSuperadmin(email);
  // Acceso estrecho: ve solo "efectivo", y solo en lectura — nunca puede
  // clasificar movimientos ni tocar ninguna otra sección del módulo.
  const esEfectivoSoloLectura = !esAdminCompleto && puedeVerEfectivoSoloLectura(email);
  if (!esAdminCompleto && !esEfectivoSoloLectura) {
    return NextResponse.json({ ok: false, error: "Solo los administradores pueden acceder a Contabilidad" }, { status: 403 });
  }
  if (!BASE_URL || !TOKEN) return NextResponse.json({ ok: false, error: "API no configurada" }, { status: 500 });

  const { ruta } = await ctx.params;
  if (!ruta.length || ruta.length > 4 || !ruta.every((s) => /^[A-Za-z0-9_-]{1,40}$/.test(s))) {
    return NextResponse.json({ ok: false, error: "Ruta no válida" }, { status: 404 });
  }
  const metodo = req.method.toUpperCase();
  if (esEfectivoSoloLectura && ruta[0] !== "efectivo") {
    return NextResponse.json({ ok: false, error: "Esta cuenta solo tiene acceso a Efectivo y caja" }, { status: 403 });
  }
  if (esEfectivoSoloLectura && metodo !== "GET") {

  return NextResponse.json({ ok: false, error: "Esta cuenta tiene acceso de solo lectura" }, { status: 403 });
}
if (metodo !== "GET" && !origenPropio(req)) {
  return NextResponse.json({ ok: false, error: "Solicitud no permitida" }, { status: 403 });
}

const path = `/v1/contabilidad/${ruta.join("/")}`;
const qs = new URL(req.url).searchParams;
qs.delete("usuario");
const headers: Record<string, string> = { Authorization: `Bearer ${TOKEN}` };
let cuerpo: string | undefined;
if (metodo === "GET") {
  qs.set("usuario", email);
} else {
  let entrada: Record<string, unknown> = {};
  try {
    const j = await req.json();
    if (j && typeof j === "object" && !Array.isArray(j)) entrada = j as Record<string, unknown>;
  } catch {
    /* cuerpo vacío */
  }
  cuerpo = JSON.stringify({ ...entrada, usuario: email });
  headers["Content-Type"] = "application/json";
}
const secreto = process.env.CONTABILIDAD_FIRMA_SECRET;
if (secreto) {
  const ts = String(Date.now());
  headers["x-kelatos-ts"] = ts;
  headers["x-kelatos-firma"] = createHmac("sha256", secreto).update(`${email}|${ts}|${metodo}|${path}`).digest("hex");
}

try {
  const res = await fetch(`${BASE_URL}${path}${qs.toString() ? `?${qs.toString()}` : ""}`, { method: metodo, headers, body: cuerpo, cache: "no-store" });
  const texto = await res.text();
  let datos: unknown;
  try {
    datos = texto ? JSON.parse(texto) : {};
  } catch {
    return NextResponse.json({ ok: false, error: res.status === 429 ? "Demasiadas solicitudes; espera un momento." : `Respuesta inválida del servidor (HTTP ${res.status})` }, { status: 502 });
  }
  // Para la cuenta de solo-lectura, se avisa en la propia respuesta — la
  // página de Efectivo usa esto para no pintar los desplegables de
  // clasificar (el backend ya los rechazaría igualmente, esto es solo
  // para no ofrecer un control que iba a fallar).
  if (esEfectivoSoloLectura && datos && typeof datos === "object" && !Array.isArray(datos)) {
    (datos as Record<string, unknown>).soloLectura = true;
  }
  return NextResponse.json(datos, { status: res.status });
} catch {

    return NextResponse.json({ ok: false, error: "No se pudo conectar con el servidor contable" }, { status: 502 });
  }
}

