import crypto from "node:crypto";
import { NextResponse } from "next/server";
import { auth } from "@/auth";
import { kelatosApiPost } from "@/lib/kelatos-api";

/**
 * Proxy de POST /v1/pedidos/:pedidoId/reportar-problema (guardarProblemaPieza
 * del original) — marca un pedido "Recibido" como Defectuosa/Rota y crea de
 * inmediato el pedido de reemplazo con sus propios proveedor/enlace/número/
 * fecha estimada, pasando la reparación a "Pieza Pendiente". El backend ya
 * existía (Fase de migración anterior) sin ningún llamador en el frontend.
 */
export async function POST(req: Request, { params }: { params: Promise<{ pedidoId: string }> }) {
  const session = await auth();
  const usuario = session?.user?.email;
  if (!usuario) return NextResponse.json({ ok: false, error: "No autenticado" }, { status: 401 });

  const { pedidoId } = await params;
  const body = (await req.json()) as {
    tipoProblema?: string;
    codigoDevolucion?: string;
    descripcion?: string;
    nuevoProveedor?: string;
    nuevoEnlace?: string;
    nuevoNumeroPedido?: string;
    nuevaFechaEstimada?: string;
    nuevoCosto?: number;
    piezaId?: string;
  };

  if (body.nuevoCosto === undefined || body.nuevoCosto === null || !(body.nuevoCosto > 0)) {
    return NextResponse.json({ ok: false, error: "El precio de compra es obligatorio" }, { status: 400 });
  }

  try {
    const resultado = await kelatosApiPost<{
      ok: boolean;
      pedidoAnterior: Record<string, unknown>;
      pedidoReemplazo: Record<string, unknown>;
      reparacion: Record<string, unknown>;
    }>(`/v1/pedidos/${encodeURIComponent(pedidoId)}/reportar-problema`, {
      requestId: crypto.randomUUID(),
      usuario,
      tipoProblema: body.tipoProblema || "defectuosa",
      codigoDevolucion: body.codigoDevolucion || "",
      descripcion: body.descripcion || "",
      nuevoProveedor: body.nuevoProveedor || "",
      nuevoEnlace: body.nuevoEnlace || "",
      nuevoNumeroPedido: body.nuevoNumeroPedido || "",
      nuevaFechaEstimada: body.nuevaFechaEstimada || "",
      nuevoCosto: body.nuevoCosto,
      piezaId: body.piezaId || "",
    });
    return NextResponse.json({
      ok: true,

      pedidoAnterior: resultado.pedidoAnterior,
      pedidoReemplazo: resultado.pedidoReemplazo,
      reparacion: resultado.reparacion,
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Error desconocido";
    return NextResponse.json({ ok: false, error: message }, { status: 502 });
  }
}

import crypto from "node:crypto";
import { NextResponse } from "next/server";
import { auth } from "@/auth";
import { kelatosApiPost } from "@/lib/kelatos-api";
import { AccionCambioEstadoPresupuesto } from "@/lib/presupuesto-cambiar-estado";

interface RespuestaCambiarEstado {
  ok: boolean;
  presupuesto: Record<string, unknown>;
  reparacion: Record<string, unknown> | null;
}

export async function POST(req: Request) {
  const session = await auth();
  const usuario = session?.user?.email;
  if (!usuario) return NextResponse.json({ ok: false, error: "No autenticado" }, { status: 401 });

  const { presupuestoId, accion, motivo, hayMas, mantenerEnAceptado } = (await req.json()) as {
    presupuestoId: string;
    accion: AccionCambioEstadoPresupuesto;
    motivo?: string;
    /** Solo aplica a accion:"aceptar" — reproduce mostrarConfirmacionAceptacion()
        del original: si hay más presupuestos por aceptar, no se rechaza al
        resto ni se cierra el estado todavía (ver GestionPresupuestosDialog,
        que ofrece "No hay más — Continuar" para ese caso). */
    hayMas?: boolean;
    /** Solo aplica a accion:"aceptar" — usado por el botón "Aceptar" del
        panel de Notificaciones (petición del usuario, 2026-09-04): ese
        botón nunca debe pasar la reparación a "En Reparación" aunque el
        presupuesto no necesite pedir pieza, se queda en "Presupuesto
        Aceptado" para que el técnico inicie la reparación manualmente. El
        botón de la ficha de la reparación no manda este campo — mantiene
        su comportamiento normal. */
    mantenerEnAceptado?: boolean;
  };

  if (!presupuestoId) return NextResponse.json({ ok: false, error: "presupuestoId es obligatorio" }, { status: 400 });
  if (!["aceptar", "rechazar", "anular"].includes(accion)) {
    return NextResponse.json({ ok: false, error: "acción no reconocida" }, { status: 400 });
  }
  if (accion === "rechazar" && !motivo?.trim()) {
    return NextResponse.json({ ok: false, error: "El motivo del rechazo es obligatorio" }, { status: 400 });
  }

  try {
    const resultado = await kelatosApiPost<RespuestaCambiarEstado>("/v1/presupuestos/cambiar-estado", {

      requestId: crypto.randomUUID(),
      origen: "dashboard",
      accion,
      presupuestoId,
      usuario,
      datos: {
        ...(motivo ? { motivo: motivo.trim() } : {}),
        ...(accion === "aceptar" && hayMas === true ? { hayMas: true } : {}),
        ...(accion === "aceptar" && mantenerEnAceptado === true ? { mantenerEnAceptado: true } : {}),
      },
    });

    return NextResponse.json({ ok: true, presupuesto: resultado.presupuesto, reparacion: resultado.reparacion });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Error desconocido";
    return NextResponse.json({ ok: false, error: message }, { status: 502 });
  }
}

import { NextResponse } from "next/server";
import { kelatosApiGet } from "@/lib/kelatos-api";
import { mapearPresupuestoEnviado } from "@/lib/presupuestos-enviados";

interface RespuestaLista<T> {
  ok: boolean;
  rows: T[];
}

interface RespuestaFila<T> {
  ok: boolean;
  row: T;
}

/**
 * GET /api/presupuestos — reproduce apiObtenerPresupuestosEnviados(), pero
 * ya no se limita a estado "enviado": el listado necesita mostrar también
 * si un presupuesto ya enviado fue aceptado/rechazado (y con qué motivo y
 * fecha), así que se trae todo salvo los "borrador" (nunca llegaron a
 * enviarse, no son "presupuestos enviados"). El endpoint genérico
 * /v1/presupuestos solo permite filtros de igualdad, así que el descarte de
 * borradores se hace aquí. Cliente/equipo se resuelven desde la reparación
 * de cada uno vía /v1/reparaciones/:resguardo — no hace falta ningún
 * endpoint dedicado nuevo en el backend.
 */
export async function GET() {
  try {
    const presupuestos = await kelatosApiGet<RespuestaLista<Parameters<typeof mapearPresupuestoEnviado>[0]>>("/v1/presupuestos", {
      order: "fecha_envio",
      direction: "desc",
      limit: 500,
    });
    presupuestos.rows = presupuestos.rows.filter((p) => p.estado !== "borrador");

    const resguardosUnicos = [...new Set(presupuestos.rows.map((p) => p.resguardo).filter(Boolean))];
    const reparaciones = await Promise.all(
      resguardosUnicos.map((resguardo) =>
        kelatosApiGet<RespuestaFila<Parameters<typeof mapearPresupuestoEnviado>[1]>>(`/v1/reparaciones/${encodeURIComponent(resguardo)}`)
          .then((r) => [resguardo, r.row] as const)
          .catch(() => [resguardo, undefined] as const)
      )
    );
    const mapaReparaciones = new Map(reparaciones);

    const lista = presupuestos.rows.map((p) => mapearPresupuestoEnviado(p, mapaReparaciones.get(p.resguardo)));

    return NextResponse.json({ ok: true, presupuestos: lista });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Error desconocido";
    return NextResponse.json({ ok: false, error: message }, { status: 502 });
  }
}

