import { NextResponse } from "next/server";
import { kelatosApiPost } from "@/lib/kelatos-api";
import { COOKIE_DISPOSITIVO, COOKIE_ENVIADA, dentroDelLimite, dispositivoDe, ipDe, leerCookie, opcionesCookie, origenPropio, pareceAutomatizado } from "@/lib/publico-seguridad";

export const dynamic = "force-dynamic";

/**
 * Enlace GENÉRICO del formulario de valoración: la página /valoracion llama
 * aquí al abrirse y recibe un código propio, de un solo uso, con el que se
 * redirige a /valoracion/<código>. Sin sesión; el backend limita cuántos
 * códigos puede pedir una misma IP.
 */

export async function POST(req: Request) {
  if (!origenPropio(req) || pareceAutomatizado(req)) return NextResponse.json({ ok: false, error: "Solicitud no permitida" }, { status: 403 });
  if (!dentroDelLimite(req, "nuevo", 12, 60 * 60_000)) return NextResponse.json({ ok: false, error: "Demasiados intentos. Inténtalo de nuevo más tarde." }, { status: 429 });
  let prueba: { desafio?: unknown; solucion?: unknown } = {};
  try {
    prueba = (await req.json()) as typeof prueba;
  } catch {
    return NextResponse.json({ ok: false, error: "Solicitud no válida" }, { status: 400 });
  }
  // Este navegador ya envió una valoración: ni siquiera se pide un código nuevo.
  if (leerCookie(req, COOKIE_ENVIADA)) return NextResponse.json({ ok: false, yaEnviada: true });
  const dispositivo = dispositivoDe(req);
  try {
    const data = await kelatosApiPost<{ ok: boolean; token: string }>("/v1/valoracion-nueva", {
      ip: ipDe(req),
      desafio: typeof prueba.desafio === "string" ? prueba.desafio.slice(0, 80) : "",
      solucion: typeof prueba.solucion === "string" ? prueba.solucion.slice(0, 16) : "",
    });
    const res = NextResponse.json({ ok: true, token: data.token });
    if (dispositivo.nuevo) res.cookies.set(COOKIE_DISPOSITIVO, dispositivo.id, opcionesCookie());
    return res;
  } catch (error) {
    const msg = error instanceof Error ? error.message : "";
    if (msg.startsWith("Demasiados intentos") || msg.startsWith("El servicio está muy ocupado")) return NextResponse.json({ ok: false, error: msg }, { status: 429 });

    if (msg.startsWith("Verificación no válida") || msg.startsWith("La verificación ha caducado")) return NextResponse.json({ ok: false, error: msg }, { status: 400 });
    return NextResponse.json({ ok: false, error: "No se pudo preparar el formulario. Inténtalo de nuevo en unos minutos." }, { status: 502 });
  }
}

import { NextResponse } from "next/server";
import { kelatosApiGet, kelatosApiPost } from "@/lib/kelatos-api";
import { COOKIE_DISPOSITIVO, COOKIE_ENVIADA, dentroDelLimite, dispositivoDe, esJson, ipDe, leerCookie, opcionesCookie, origenPropio, pareceAutomatizado } from "@/lib/publico-seguridad";

export const dynamic = "force-dynamic";

/**
 * Formulario PÚBLICO de valoración (clientes que puntúan mal la encuesta).
 * Sin sesión: la única autoridad es el token del enlace, de un solo uso, que
 * valida el backend. Aquí solo se reenvían campos conocidos y se limita el
 * tamaño; el navegador del cliente nunca habla con el backend directamente.
 */

const TOKEN_VALIDO = /^[A-Za-z0-9_-]{20,64}$/;
const MAX_BYTES = 8 * 1024;

// Solo se muestran al cliente los mensajes que sabemos que son seguros.
const MENSAJES_SEGUROS = [
  "Escribe un correo electrónico válido",
  "Cuéntanos qué motivo o escribe un comentario",
  "Este enlace ya se ha usado",
  "Este enlace ha caducado",
  "Este enlace no es válido",
  "Con este correo ya se ha enviado una valoración",
  "Demasiados intentos. Inténtalo de nuevo más tarde.",
  "Espera unos segundos antes de enviar el formulario",
  "Inicia sesión con Google para enviar tu valoración",
  "No se pudo verificar tu cuenta de Google. Inicia sesión de nuevo.",
  "Tu cuenta de Google no tiene un correo verificado",
  "Tu cuenta de Google no tiene un correo válido",
];


export async function GET(req: Request, { params }: { params: Promise<{ token: string }> }) {
  const { token } = await params;
  if (!TOKEN_VALIDO.test(token)) return NextResponse.json({ ok: true, estado: "invalido" });
  if (pareceAutomatizado(req)) return NextResponse.json({ ok: false, error: "Solicitud no permitida" }, { status: 403 });
  if (!dentroDelLimite(req, "consulta", 60, 10 * 60_000)) return NextResponse.json({ ok: false, error: "Demasiados intentos. Inténtalo de nuevo más tarde." }, { status: 429 });
  const dispositivo = dispositivoDe(req);
  const conCookie = (res: NextResponse) => {
    if (dispositivo.nuevo) res.cookies.set(COOKIE_DISPOSITIVO, dispositivo.id, opcionesCookie());
    return res;
  };
  // Este navegador ya envió una valoración.

  if (leerCookie(req, COOKIE_ENVIADA)) return conCookie(NextResponse.json({ ok: true, estado: "usado" }));
  try {
    const data = await kelatosApiGet<{ ok: boolean; estado: string; anonimo?: boolean; googleClientId?: string | null; nombre?: string | null; servicio?: string | null; motivos?: { id: string; etiqueta: string }[] }>(
      `/v1/valoracion/${token}`,
      { ip: ipDe(req) }
    );
    return conCookie(NextResponse.json({ ok: true, estado: data.estado, anonimo: data.anonimo === true, googleClientId: data.googleClientId ?? null, nombre: data.nombre ?? null, servicio: data.servicio ?? null, motivos: data.motivos ?? [] }));
  } catch (error) {
    const msg = error instanceof Error ? error.message : "";
    if (MENSAJES_SEGUROS.includes(msg)) return NextResponse.json({ ok: false, error: msg }, { status: 429 });
    return NextResponse.json({ ok: false, error: "No se pudo cargar el formulario. Inténtalo de nuevo en unos minutos." }, { status: 502 });
  }
}

export async function POST(req: Request, { params }: { params: Promise<{ token: string }> }) {
  const { token } = await params;
  if (!origenPropio(req) || pareceAutomatizado(req)) return NextResponse.json({ ok: false, error: "Solicitud no permitida" }, { status: 403 });
  if (!dentroDelLimite(req, "envio", 15, 10 * 60_000)) return NextResponse.json({ ok: false, error: "Demasiados intentos. Inténtalo de nuevo más tarde." }, { status: 429 });
  if (!esJson(req)) return NextResponse.json({ ok: false, error: "Solicitud no válida" }, { status: 415 });
  if (!TOKEN_VALIDO.test(token)) return NextResponse.json({ ok: false, error: "Este enlace no es válido" }, { status: 404 });

  const crudo = await req.text();
  if (crudo.length > MAX_BYTES) return NextResponse.json({ ok: false, error: "El mensaje es demasiado largo" }, { status: 413 });
  let b: Record<string, unknown>;
  try {
    b = JSON.parse(crudo) as Record<string, unknown>;
  } catch {
    return NextResponse.json({ ok: false, error: "Solicitud no válida" }, { status: 400 });
  }

  const dispositivo = dispositivoDe(req);
  try {
    await kelatosApiPost(`/v1/valoracion/${token}`, {
      dispositivo: dispositivo.id,

      email: typeof b.email === "string" ? b.email.slice(0, 254) : "",
      credential: typeof b.credential === "string" ? b.credential.slice(0, 4096) : "",
      motivos: Array.isArray(b.motivos) ? b.motivos.filter((m) => typeof m === "string").slice(0, 10) : [],
      comentario: typeof b.comentario === "string" ? b.comentario.slice(0, 1500) : "",
      contactar: b.contactar === true,
      nombre: typeof b.nombre === "string" ? b.nombre.slice(0, 120) : "",
      telefono: typeof b.telefono === "string" ? b.telefono.slice(0, 30) : "",
      resguardo: typeof b.resguardo === "string" ? b.resguardo.slice(0, 40) : "",
      website: typeof b.website === "string" ? b.website.slice(0, 100) : "",
      ip: ipDe(req),
    });
    // Marca este navegador como "ya envió": no podrá abrir otro formulario.
    const res = NextResponse.json({ ok: true });
    res.cookies.set(COOKIE_ENVIADA, "1", opcionesCookie());
    res.cookies.set(COOKIE_DISPOSITIVO, dispositivo.id, opcionesCookie());
    return res;
  } catch (error) {
    const msg = error instanceof Error ? error.message : "";
    if (MENSAJES_SEGUROS.includes(msg)) return NextResponse.json({ ok: false, error: msg }, { status: 409 });
    return NextResponse.json({ ok: false, error: "No se pudo enviar. Inténtalo de nuevo en unos minutos." }, { status: 502 });
  }
}

import crypto from "node:crypto";
import { NextResponse } from "next/server";
import { auth } from "@/auth";
import { kelatosApiPost } from "@/lib/kelatos-api";

/**
 * Reproduce apiPeekNumeroFactura('1') — solo previsualiza el próximo
 * número de la serie 1 sin reservarlo (dryRun: la reserva nunca se
 * confirma, se hace ROLLBACK). El requestId es de un solo uso, exigido
 * por la ruta pero descartado de inmediato.
 */
export async function GET() {
  const session = await auth();
  if (!session?.user?.email) return NextResponse.json({ ok: false, error: "No autenticado" }, { status: 401 });

  try {
    const requestId = crypto.randomUUID();
    const lineas = [{ descripcion: "peek", cantidad: 1, precio: 0 }];
    const resultado = await kelatosApiPost<{ ok: boolean; preview: { numeroFacturaTentativo: string } }>("/v1/facturas/entidades/preparar", {
      requestId,
      usuario: session.user.email,
      tipo: "pedido",
      payloadHash: crypto.createHash("sha256").update(requestId).digest("hex"),
      dryRun: true,
      datos: { lineas },
    });
    return NextResponse.json({ ok: true, numero: resultado.preview.numeroFacturaTentativo });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Error desconocido";
    return NextResponse.json({ ok: false, error: message }, { status: 502 });
  }
}

import crypto from "node:crypto";
import { NextResponse } from "next/server";
import { auth } from "@/auth";
import { kelatosApiPost } from "@/lib/kelatos-api";
import type { DatosNuevoPedido, ResultadoNuevoPedido } from "@/lib/ventas";

const LABELS_PAGO: Record<string, string> = { efectivo: "Efectivo", tarjeta: "Tarjeta bancaria", tarjeta_virtual: "Tarjeta virtual", transferencia: "Transferencia bancaria", bizum: "Bizum" };

function fechaHoyEs(): string {
  return new Date().toLocaleDateString("es-ES", { timeZone: "Europe/Madrid" });
}

/**
 * POST /v1/ventas nunca toca kelatos_app.clientes (a diferencia de
 * /v1/reparaciones/altas/confirmar, que sí registra/actualiza el cliente
 * como parte de la misma transacción) — un pedido de piezas para un
 * cliente nuevo no dejaba ningún rastro en el directorio de clientes. Bug
 * real reportado por el usuario, 2026-08-27: "los clientes registrados
 * para los pedido de piezas no se están registrando en el listado de
 * clientes". POST /v1/clientes/upsert ya existía para exactamente este
 * caso ("cliente asociado a una operación que no lo crea por sí misma")
 * pero no tenía ningún llamador — mismas reglas de coincidencia que el
 * alta de reparación (por DNI, o ≥2 de teléfono/email/nombre), así que
 * un cliente que ya existe se actualiza en vez de duplicarse. Best-effort:
 * si falla, no bloquea la creación del pedido (el directorio de clientes
 * es secundario respecto al pedido en sí).
 */
async function registrarClienteVenta(usuario: string, datos: { clienteNombre: string; clienteTelefono: string; clienteEmail: string; clienteDni?: string; clienteDireccion?: string }) {
  const nombre = datos.clienteNombre.trim();
  const telefono = datos.clienteTelefono.trim();
  const email = datos.clienteEmail.trim();
  const dniCif = (datos.clienteDni || "").trim();
  const direccion = (datos.clienteDireccion || "").trim();
  if (!nombre && !telefono && !email && !dniCif) return;
  try {
    const payloadHash = crypto.createHash("sha256").update(JSON.stringify({ nombre, telefono, email, dniCif, direccion })).digest("hex");
    await kelatosApiPost("/v1/clientes/upsert", {
      requestId: crypto.randomUUID(),

      usuario,
      payloadHash,
      nombre, telefono, email, dniCif, direccion,
    });
  } catch (error) {
    console.error("No se pudo registrar/actualizar el cliente del pedido en el directorio:", error);
  }
}

/**
 * Orquesta generarFacturaPedido() del original — reproduce el saga
 * genérico /v1/facturas/entidades/* (preparar→iniciar→generar-pdf→
 * confirmar, ya existente sin ningún llamador) + POST /v1/ventas, en el
 * mismo orden que el original: primero reserva el número fiscal real y
 * genera el PDF, y solo entonces crea la venta con ese número. En modo
 * garantía no hay saga fiscal — se crea la venta directamente, igual que
 * el original.
 */
export async function POST(req: Request) {
  const session = await auth();
  const usuario = session?.user?.email;
  if (!usuario) return NextResponse.json({ ok: false, error: "No autenticado" }, { status: 401 });

  const body = (await req.json()) as { requestId: string; datos: DatosNuevoPedido };
  const { requestId, datos } = body;
  if (!requestId || !/^[0-9a-f-]{36}$/i.test(requestId)) {
    return NextResponse.json({ ok: false, error: "requestId inválido" }, { status: 400 });
  }
  // El nombre nunca es obligatorio en modo Ticket (solo se pide correo,
  // igual que Ticket Manual) — petición del usuario, 2026-09-02.
  if (!datos.modoTicket && !datos.clienteNombre.trim()) return NextResponse.json({ ok: false, error: "El nombre del cliente es obligatorio" }, { status: 400 });
  if (datos.items.length === 0) return NextResponse.json({ ok: false, error: "Añade al menos una pieza" }, { status: 400 });
  for (const [i, it] of datos.items.entries()) {
    if (!it.descripcion.trim()) return NextResponse.json({ ok: false, error: `La descripción de la pieza ${i + 1} es obligatoria` }, { status: 400 });
    if (!datos.esGarantia && it.precioUnitario <= 0) return NextResponse.json({ ok: false, error: `El precio de la pieza ${i + 1} debe ser mayor que 0` }, { status: 400 });
  }

  try {
    // ── Modo garantía: sin saga fiscal ──────────────────────────────────
    if (datos.esGarantia) {
      await registrarClienteVenta(usuario, datos);

  const itemsVenta = datos.items.map((it) => ({ descripcion: it.descripcion.trim(), costo: 0, precio: 0 }));
  const resVenta = await kelatosApiPost<{ ok: boolean; venta_id: string }>("/v1/ventas", {
    requestId,
    usuario,
    es_garantia: true,
    cliente_nombre: datos.clienteNombre.trim(),
    cliente_telefono: datos.clienteTelefono.trim(),
    cliente_email: datos.clienteEmail.trim(),
    observaciones: datos.observaciones.trim(),
    items: itemsVenta,
  });
  const resultado: ResultadoNuevoPedido = { ventaId: resVenta.venta_id, numeroFactura: "", numeroTicket: "", urlPdf: "" };
  return NextResponse.json({ ok: true, ...resultado });
}

// ── Modo ticket: venta pagada de verdad, pero con un Ticket de Venta
// (Serie 4, no fiscal) en vez de una Factura real — sin saga fiscal
// (crea la venta directamente, como Garantía), pero encadenando la
// generación del ticket sobre la venta ya creada. Petición del
// usuario, 2026-08-28: "añade tickets también aquí". ────────────────
if (datos.modoTicket) {
  if (!datos.formaPago) return NextResponse.json({ ok: false, error: "Selecciona la forma de pago" }, { status: 400 });
  if (datos.formaPago === "tarjeta" && !datos.banco) return NextResponse.json({ ok: false, error: "Selecciona el banco" }, { status: 400 });

  await registrarClienteVenta(usuario, datos);
  const itemsVenta = datos.items.map((it) => ({ descripcion: it.descripcion.trim(), costo: 0, precio: it.cantidad * it.precioUnitario }));
  const resVenta = await kelatosApiPost<{ ok: boolean; venta_id: string }>("/v1/ventas", {
    requestId,
    usuario,
    es_garantia: false,
    es_ticket: true,
    cliente_nombre: datos.clienteNombre.trim(),
    cliente_telefono: datos.clienteTelefono.trim(),
    cliente_email: datos.clienteEmail.trim(),
    observaciones: datos.observaciones.trim(),
    items: itemsVenta,
  });

  const descuentoPct = Math.min(100, Math.max(0, Number(datos.descuentoPct) || 0));
  const lineasTicket = datos.items.map((it) => ({
    descripcion: it.descripcion.trim(),

    cantidad: it.cantidad,
    precio: it.precioUnitario,
    descuento: descuentoPct,
  }));

  let ticket: { ok: boolean; numeroTicket: string; urlTicket: string };
  try {
    ticket = await kelatosApiPost<{ ok: boolean; numeroTicket: string; urlTicket: string }>(
      `/v1/ventas/${resVenta.venta_id}/ticket-venta`,
      {
        requestId: crypto.randomUUID(),
        usuario,
        lineas: lineasTicket,
        estado: datos.estadoFactura || "Cobrada",
        formaPago: datos.formaPago,
        banco: datos.formaPago === "tarjeta" ? datos.banco : "",
        referencia: datos.formaPago === "transferencia" ? datos.referencia : "",
        formaPagoDesglose: datos.formaPago === "multiforma" ? datos.formaPagoDesglose : undefined,
      }
    );
  } catch (errorTicket) {
    const mensaje = errorTicket instanceof Error ? errorTicket.message : "Error desconocido generando el ticket";
    return NextResponse.json({
      ok: false,
      error: `El pedido #${resVenta.venta_id} se creó pero no se pudo generar el ticket: ${mensaje}. Puedes generarlo desde el detalle del pedido.`,
    }, { status: 502 });
  }

  const resultado: ResultadoNuevoPedido = { ventaId: resVenta.venta_id, numeroFactura: "", numeroTicket: ticket.numeroTicket, urlPdf: ticket.urlTicket };
  return NextResponse.json({ ok: true, ...resultado });
}

// ── Modo normal: reservar número real + generar PDF + crear venta ───
if (!datos.formaPago) return NextResponse.json({ ok: false, error: "Selecciona la forma de pago" }, { status: 400 });
if (datos.formaPago === "tarjeta" && !datos.banco) return NextResponse.json({ ok: false, error: "Selecciona el banco" }, { status: 400 });

await registrarClienteVenta(usuario, datos);

const descuentoPct = Math.min(100, Math.max(0, Number(datos.descuentoPct) || 0));
const lineas = datos.items.map((it) => ({
  descripcion: it.descripcion.trim(),
  cantidad: it.cantidad,
  precio: it.precioUnitario,
  descuento: descuentoPct,
}));

const payloadHash = crypto.createHash("sha256").update(JSON.stringify({ tipo: "pedido", lineas })).digest("hex");
const preparar = await kelatosApiPost<{ ok: boolean; numeroFactura: string }>("/v1/facturas/entidades/preparar", {
  requestId,
  usuario,
  tipo: "pedido",
  payloadHash,
  datos: { lineas },
});

const iniciar = await kelatosApiPost<{ ok: boolean; operacion: { estado: string } }>("/v1/facturas/entidades/iniciar", { requestId, usuario });
if (iniciar.operacion.estado === "resultado_desconocido") {
  return NextResponse.json({
    ok: false,
    error: `El número ${preparar.numeroFactura} quedó en un estado incierto en un intento anterior. No se ha generado un PDF nuevo para evitar duplicar el número — contacta con soporte para reconciliarlo manualmente.`,
  }, { status: 409 });
}

let generado;
try {
  generado = await kelatosApiPost<{ ok: boolean; url: string; total: number; baseImponible: number }>("/v1/facturas/entidades/generar-pdf", {
    datos: {
      numero: preparar.numeroFactura,
      fecha: fechaHoyEs(),
      cliente: {
        nombre: datos.clienteNombre.trim(),
        dni: datos.clienteDni.trim(),
        telefono: datos.clienteTelefono.trim(),
        email: datos.clienteEmail.trim(),
        direccion: datos.clienteDireccion.trim(),
        codigo: "",
      },
      formaPago: datos.formaPago,
      banco: datos.formaPago === "tarjeta" ? datos.banco : "",
      estadoFactura: datos.estadoFactura || "Cobrada",
      lineas,
    },
  });
} catch (errorPdf) {
  const mensaje = errorPdf instanceof Error ? errorPdf.message : "Error desconocido generando el PDF";
  await kelatosApiPost("/v1/facturas/entidades/fallar", { requestId, errorTecnico: mensaje.slice(0, 500) }).catch(() => {});
  return NextResponse.json({
    ok: false,
    error: `El número de factura ${preparar.numeroFactura} ya ha sido reservado y no se puede reutilizar. Error generando el PDF: ${mensaje}`,
  }, { status: 502 });
}

// El original guarda cada item con el precio ANTES de aplicar el

// descuento (el descuento solo afecta a las líneas de la factura, no
// a los items de la venta) — se replica esa misma inconsistencia real.
const metodoPagoFinal = datos.formaPago === "tarjeta" && datos.banco ? `${datos.banco} · Tarjeta bancaria` : LABELS_PAGO[datos.formaPago] || datos.formaPago;
const itemsVenta = datos.items.map((it) => ({ descripcion: it.descripcion.trim(), costo: 0, precio: it.cantidad * it.precioUnitario }));

// Cliente exactamente como se imprimió en el PDF — se guarda como foto
// (cliente_factura) para poder precargar el formulario de devolución/
// rectificativa más tarde con los mismos datos fiscales, sin depender
// de que el cliente_nombre/telefono/email de la venta (editables después
// desde el detalle del pedido) sigan siendo los mismos.
const clienteFactura = {
  nombre: datos.clienteNombre.trim(), dni: datos.clienteDni.trim(),
  telefono: datos.clienteTelefono.trim(), direccion: datos.clienteDireccion.trim(), email: datos.clienteEmail.trim(),
};

let resVenta: { ok: boolean; venta_id: string };
try {
  resVenta = await kelatosApiPost<{ ok: boolean; venta_id: string }>("/v1/ventas", {
    requestId,
    usuario,
    es_garantia: false,
    cliente_nombre: datos.clienteNombre.trim(),
    cliente_telefono: datos.clienteTelefono.trim(),
    cliente_email: datos.clienteEmail.trim(),
    observaciones: datos.observaciones.trim(),
    numero_factura: preparar.numeroFactura,
    metodo_pago: metodoPagoFinal,
    items: itemsVenta,
    url_factura: generado.url,
    total_factura: generado.baseImponible,
    estado_factura: datos.estadoFactura || "Cobrada",
    forma_pago_factura: datos.formaPago,
    banco_factura: datos.formaPago === "tarjeta" ? datos.banco : "",
    referencia_factura: datos.formaPago === "transferencia" ? datos.referencia : "",
    forma_pago_factura_desglose: datos.formaPago === "multiforma" ? datos.formaPagoDesglose : undefined,
    lineas_factura: lineas,
    cliente_factura: clienteFactura,
  });
} catch (errorVenta) {

      const mensaje = errorVenta instanceof Error ? errorVenta.message : "Error desconocido creando la venta";
      return NextResponse.json({
        ok: false,
        error: `La factura ${preparar.numeroFactura} ya se generó (PDF: ${generado.url}) pero no se pudo registrar el pedido: ${mensaje}. Reintenta — el mismo requestId no reservará un número nuevo.`,
      }, { status: 502 });
    }

    try {
      await kelatosApiPost("/v1/facturas/entidades/confirmar", { requestId, usuario, urlPdf: generado.url, entidadId: resVenta.venta_id });
    } catch (errorConfirmar) {
      console.error("No se pudo confirmar la reserva fiscal del pedido (resultado desconocido):", errorConfirmar);
    }

    const resultado: ResultadoNuevoPedido = { ventaId: resVenta.venta_id, numeroFactura: preparar.numeroFactura, numeroTicket: "", urlPdf: generado.url };
    return NextResponse.json({ ok: true, ...resultado });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Error desconocido";
    return NextResponse.json({ ok: false, error: message }, { status: 502 });
  }
}

import crypto from "node:crypto";
