import { NextResponse } from "next/server";
import { auth } from "@/auth";
import { kelatosApiGet } from "@/lib/kelatos-api";
import type { WebhookEvento } from "@/lib/webhook-eventos";

/** GET — lista de eventos del webhook de presupuestos, para el panel de notificaciones. */
export async function GET(request: Request) {
  const session = await auth();
  if (!session?.user?.email) return NextResponse.json({ ok: false, error: "No autenticado" }, { status: 401 });

  const url = new URL(request.url);
  const leida = url.searchParams.get("leida") ?? undefined;
  const porPagina = url.searchParams.get("porPagina") ?? undefined;

  try {
    const data = await kelatosApiGet<{ ok: boolean; eventos: WebhookEvento[]; no_leidas: number }>(
      "/v1/lecturas/webhook-eventos",
      { leida, porPagina }
    );
    return NextResponse.json({ ok: true, eventos: data.eventos, noLeidas: data.no_leidas });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Error desconocido";
    return NextResponse.json({ ok: false, error: message }, { status: 502 });
  }
}

import { NextResponse } from "next/server";
import { auth } from "@/auth";
import { kelatosApiPost } from "@/lib/kelatos-api";

/** POST — responde por correo a la consulta del cliente de un evento del webhook de presupuestos. */
export async function POST(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const session = await auth();
  const usuario = session?.user?.email;
  if (!usuario) return NextResponse.json({ ok: false, error: "No autenticado" }, { status: 401 });

  const { id } = await params;
  const { mensaje } = (await req.json()) as { mensaje: string };
  if (!mensaje?.trim()) return NextResponse.json({ ok: false, error: "El mensaje es obligatorio" }, { status: 400 });

  try {
    const resultado = await kelatosApiPost<{ ok: boolean; enHilo: boolean }>(
      `/v1/webhook-eventos/${encodeURIComponent(id)}/responder`,
      { usuario, mensaje: mensaje.trim() }
    );
    return NextResponse.json({ ok: true, enHilo: resultado.enHilo });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Error desconocido";
    return NextResponse.json({ ok: false, error: message }, { status: 502 });
  }
}

import { NextResponse } from "next/server";
import { auth } from "@/auth";
import { kelatosApiPost } from "@/lib/kelatos-api";

/** PATCH — marca un evento del webhook como leído (equivalente puntual a apiMarcarEventosLeidos, que en el original marca todos a la vez). */
export async function PATCH(_request: Request, { params }: { params: Promise<{ id: string }> }) {
  const session = await auth();
  if (!session?.user?.email) return NextResponse.json({ ok: false, error: "No autenticado" }, { status: 401 });

  const { id } = await params;

  try {
    await kelatosApiPost(`/v1/webhook_eventos/${encodeURIComponent(id)}`, { leida: true }, "PATCH");
    return NextResponse.json({ ok: true });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Error desconocido";
    return NextResponse.json({ ok: false, error: message }, { status: 502 });
  }
}

