import { Pie, PieChart, Cell } from "recharts";
import { ChartConfig, ChartContainer, ChartTooltip, ChartTooltipContent, ChartLegend, ChartLegendContent } from "@/components/ui/chart";
import { formatDuracion, type RemoteWorkerAppUsage } from "@/lib/remote-workers";
import { AppIcon } from "./app-icon";

const COLORES = ["var(--chart-1)", "var(--chart-2)", "var(--chart-3)", "var(--chart-4)", "var(--chart-5)"];
const MAX_SEGMENTOS = 5;

/** Distribución de aplicaciones del día — PieChart de recharts dentro del
    wrapper shadcn (mismo wiring que ganancia-chart.tsx en Reportes, con
    Pie en vez de Bar). Las apps fuera del top 5 se agrupan en "Otras". */
export function AppDistributionChart({ apps }: { apps: RemoteWorkerAppUsage[] }) {
  if (apps.length === 0) {
    return <p className="py-8 text-center text-sm text-muted-foreground">Sin datos de aplicaciones hoy</p>;
  }

  const top = apps.slice(0, MAX_SEGMENTOS);
  const resto = apps.slice(MAX_SEGMENTOS);
  const otras = resto.reduce((n, a) => n + a.seconds, 0);
  const datos = otras > 0
    ? [...top, { applicationName: "Otras", seconds: otras, percentage: resto.reduce((n, a) => n + a.percentage, 0) }]
    : top;

  const chartConfig: ChartConfig = Object.fromEntries(
    datos.map((d, i) => [
      d.applicationName,
      {
        label: d.applicationName,
        color: COLORES[i % COLORES.length],
        // Logo real de la app en vez del punto de color, cuando se
        // reconoce el ejecutable (ver app-icon.tsx) — "Otras" (grupo
        // agregado sin ejecutable propio) cae al icono generico.
        icon: () => <AppIcon applicationName={d.applicationName} className="size-3.5" />,
      },
    ]),
  );

  return (
    <ChartContainer config={chartConfig} className="mx-auto aspect-square h-56">
      <PieChart>
        <ChartTooltip
          content={<ChartTooltipContent hideLabel formatter={(_v, _n, item) => `${(item.payload as RemoteWorkerAppUsage).applicationName}: ${formatDuracion((item.payload as RemoteWorkerAppUsage).seconds)} (${(item.payload as RemoteWorkerAppUsage).percentage}%)`} />}
        />

  ["hojas de cálculo de google", "googlesheets"],
  ["google sheets", "googlesheets"],
  ["documentos de google", "googledocs"],
  ["google docs", "googledocs"],
  ["hostinger", "hostinger"],
  ["vercel", "vercel"],
  ["portainer", "portainer"],
  ["chatwoot", "chatwoot"],
  ["whatsapp", "whatsapp"],
];

function slugParaTitulo(windowTitle: string): string | undefined {
  const t = windowTitle.toLowerCase();
  const match = WEB_APP_KEYWORD_SLUG.find(([kw]) => t.includes(kw));
  return match?.[1];
}

function slugParaApp(applicationName: string): string | undefined {
  return EXE_ICON_SLUG[applicationName.trim().toLowerCase()];
}

export function AppIcon({
  applicationName,
  windowTitle,
  className = "size-4 shrink-0",
}: {
  applicationName: string;
  /** Título de la ventana/pestaña — opcional; sin él solo se distingue
      por ejecutable (comportamiento anterior), igual que necesita el
      gráfico de distribución de apps, que agrega todo un día por
      ejecutable y no tiene un único título que mirar. */
  windowTitle?: string | null;
  className?: string;
}) {
  const [fallo, setFallo] = useState(false);
  const exeLower = applicationName.trim().toLowerCase();
  const tituloLower = (windowTitle || "").toLowerCase();

  // Kelatos es la propia app — logo local, no depende de Simple Icons.
  if (tituloLower.includes("kelatos")) {
    // eslint-disable-next-line @next/next/no-img-element -- icono pequeño de tamaño variable (className), no encaja bien con next/image
    return <img src="/logos/kelatos-icono.png" alt="" className={className} />;
  }

  const slugWeb = windowTitle && NAVEGADORES.has(exeLower) ? slugParaTitulo(windowTitle) : undefined;
  const slug = slugWeb || slugParaApp(applicationName);

  if (!slug || fallo) {
    const Fallback = EXE_ICON_FALLBACK[exeLower] || Monitor;
    return <Fallback className={`${className} text-muted-foreground`} />;
  }

  return (
    // eslint-disable-next-line @next/next/no-img-element -- icono pequeño de tamaño variable (className), no encaja bien con next/image
    <img
      src={`/logos/brands/${slug}.svg`}
      alt=""
      className={className}
      onError={() => setFallo(true)}
    />
  );
}

