          Asistencia → Remote Workers para poder usar el botón de Reunión.
        </p>
      </CardContent>
    </Card>
  );
}

const activa = dispositivo.reunionActiva;
const segundosEnCurso = activa ? Math.max(0, Math.floor((ahora - new Date(activa.inicio).getTime()) / 1000)) : 0;

return (
