  codigo: string;
  paso: number;
  datos: DatosFormularioCliente;
  guardadoEn: number;
}

function leerBorrador(): BorradorGuardado | null {
  try {
    const raw = localStorage.getItem(BORRADOR_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as Partial<BorradorGuardado> | null;
    if (!parsed || typeof parsed !== "object" || !parsed.codigo || !parsed.datos) return null;
    if (Date.now() - (parsed.guardadoEn || 0) > BORRADOR_MAX_EDAD_MS) return null;
    return parsed as BorradorGuardado;
  } catch {
    return null;
  }
}

function guardarBorrador(borrador: BorradorGuardado) {
  try {
    localStorage.setItem(BORRADOR_KEY, JSON.stringify(borrador));
  } catch {
    // Cuota de localStorage superada — normalmente por las fotos en
    // base64. Se reintenta sin fotos/firma para no perder al menos los
    // datos de texto, que son los tediosos de rellenar de nuevo; si ni
    // así cabe, se deja sin guardar en silencio (no debe romper el envío).
    try {
      localStorage.setItem(BORRADOR_KEY, JSON.stringify({ ...borrador, datos: { ...borrador.datos, fotos: [], firmaBase64: "" } }));
    } catch {
      // Sin espacio ni para eso — se ignora.
    }
  }
}

// Etiquetas cortas para el aviso resumido cuando falta algo por rellenar —
// petición del usuario, 2026-09-18: "que salga un modal pequeño de aviso
// encima [...] si son un montón de cosas un poco más resumido". Se separan
// de los mensajes largos de `errores` (esos siguen bajo cada campo tal
// cual) porque un toast con 5 frases completas no cabe ni se lee bien.
const ETIQUETAS_CAMPO_AVISO: Record<string, string> = {
  tipoDocumento: "Factura o Ticket",
  dniCif: "DNI/NIF",
  nombre: "Nombre",
  viaTipo: "Tipo de vía",

  viaNombre: "Nombre de la vía",
  cp: "Código postal",
  localidad: "Localidad",
  provincia: "Provincia",
  telefono: "Teléfono",
  email: "Email",
  tipoProducto: "Tipo de producto",
  tipoOtro: "Descripción del producto",
  marca: "Marca",
  modelo: "Modelo",
  cintas: "Cantidad de cintas",
  sintoma: "Síntoma de la avería",
  enciende: "¿Enciende?",
  golpe: "¿Ha sufrido golpe?",
  humedad: "¿Ha sufrido humedad?",
  reparacionAnterior: "¿Reparación anterior?",
  aceptaCondiciones: "Aceptar las condiciones",
  fotos: "Foto del equipo",
  firma: "Firma",
};

function etiquetasCamposFaltantes(err: Record<string, string>): string[] {
  return Object.keys(err).map((k) => ETIQUETAS_CAMPO_AVISO[k] || k);
}

function borrarBorrador() {
  try {
    localStorage.removeItem(BORRADOR_KEY);
  } catch {
    // No-op — si localStorage no está disponible, tampoco había nada que borrar.
  }
}

