      </div>
    </button>
    {errorProceso && <p className="mt-1.5 text-xs text-destructive">{errorProceso}</p>}
    {fotos.length > 0 && (

    ctx.beginPath();
    ctx.moveTo(x, y);
  }

  function mover(e: React.MouseEvent | React.TouchEvent) {
