function PantallaCodigoAcceso({ onAcceso }: { onAcceso: (codigo: string) => void }) {
  const [codigo, setCodigo] = useState("");
  const [validando, setValidando] = useState(false);
  const [error, setError] = useState("");

  async function validar(e: React.FormEvent) {
    e.preventDefault();
    if (!codigo.trim()) return;

    setValidando(true);
    setError("");
    try {
      const res = await fetch("/api/formulario-cliente/validar-codigo", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ codigo }),
      });
      const data = await res.json();
      if (!data.ok || !data.valido) throw new Error(data.error || "Código incorrecto.");
      onAcceso(codigo.trim());
    } catch (e2) {
      setError(e2 instanceof Error ? e2.message : "Error desconocido");
    } finally {
      setValidando(false);
    }
  }

  return (
    <FondoPagina>
      <form onSubmit={validar} className="mx-auto h-fit w-full max-w-sm rounded-xl border bg-card p-8 text-center shadow-sm lg:mt-16">
        <span className="mx-auto mb-3 flex size-14 items-center justify-center rounded-full bg-amber-500/10 text-amber-600 dark:text-amber-400">
          <Lock className="size-7" />
        </span>
        <h1 className="mb-1 text-base font-semibold">Código de acceso</h1>
        <p className="mb-5 text-sm text-muted-foreground">Pide el código de 6 dígitos al personal de la tienda.</p>
        <Input
          value={codigo}
          onChange={(e) => setCodigo(e.target.value.replace(/[^\d]/g, "").slice(0, 6))}
          inputMode="numeric"
          autoFocus
          className="h-14 text-center text-2xl font-bold tracking-[0.3em]"
          placeholder="------"
        />
        {error && (
          <div className="mt-3 flex items-center justify-center gap-1.5 text-sm text-destructive">
            <CloseCircle className="size-3.5" />
            {error}
          </div>
        )}
        <Button type="submit" disabled={validando || codigo.length < 6} className="mt-4 h-11 w-full">
          {validando ? "Comprobando…" : "Continuar"}
        </Button>
      </form>
    </FondoPagina>
  );
}

"use client";

import { Suspense, useEffect, useRef, useState } from "react";
import { useSearchParams } from "next/navigation";

type Seccion = "cargando" | "error" | "yaEntregado" | "cancelado" | "formulario" | "exito";

interface DatosEntrega {
  ventaId: string;
  nombre: string;
  items: string[];
}

function FormularioEntregaVentaInterno() {
  const params = useSearchParams();
  const ventaId = params.get("ventaId") || "";
  const token = params.get("token") || "";

  const [seccion, setSeccion] = useState<Seccion>("cargando");
  const [datos, setDatos] = useState<DatosEntrega | null>(null);
  const [dni, setDni] = useState("");
  const [error, setError] = useState("");
  const [enviando, setEnviando] = useState(false);
  // Bloqueo inmediato contra doble clic: el estado `enviando` tarda en reflejarse y dos clics seguidos
  // entraban antes de que el botón se desactivara.
  const enviandoRef = useRef(false);
  const [yaEstabaEntregado, setYaEstabaEntregado] = useState(false);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const dibujandoRef = useRef(false);
  const hayFirmaRef = useRef(false);

  useEffect(() => {
    if (!ventaId || !token) {
      setError("Enlace inválido: falta el pedido o el token.");
      setSeccion("error");
      return;
    }
    fetch(`/api/formulario-entrega-venta?ventaId=${encodeURIComponent(ventaId)}&token=${encodeURIComponent(token)}`)
      .then((r) => r.json())
      .then((data) => {
        if (!data.ok) {
          setError(data.error || "No se encontró el pedido.");
          setSeccion("error");
          return;
        }
        if (data.estado === "Entregado") {
          setSeccion("yaEntregado");
          return;
        }
        if (data.estado === "Cancelado") {
          setSeccion("cancelado");
          return;
        }
        setDatos(data);
        setSeccion("formulario");
      })
      .catch((e) => {
        setError(e instanceof Error ? e.message : "Error desconocido");
        setSeccion("error");
      });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (seccion !== "formulario") return;
    const canvas = canvasRef.current;

  if (!canvas) return;
  const ctx = canvas.getContext("2d");
  if (!ctx) return;
  const dpr = window.devicePixelRatio || 1;
  const cssW = canvas.parentElement?.clientWidth || 340;
  const cssH = 180;
  canvas.width = cssW * dpr;
  canvas.height = cssH * dpr;
  canvas.style.width = cssW + "px";
  canvas.style.height = cssH + "px";
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.scale(dpr, dpr);
  ctx.strokeStyle = "#1a1a2e";
  ctx.lineWidth = 2.5;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
}, [seccion]);

function getPos(e: React.MouseEvent | React.TouchEvent) {
  const canvas = canvasRef.current!;
  const r = canvas.getBoundingClientRect();
  const src = "touches" in e ? e.touches[0] : e;
  return { x: src.clientX - r.left, y: src.clientY - r.top };
}

function startDraw(e: React.MouseEvent | React.TouchEvent) {
  dibujandoRef.current = true;
  const ctx = canvasRef.current?.getContext("2d");
  const p = getPos(e);
  ctx?.beginPath();
  ctx?.moveTo(p.x, p.y);
}
function moveDraw(e: React.MouseEvent | React.TouchEvent) {
  if (!dibujandoRef.current) return;
  const ctx = canvasRef.current?.getContext("2d");
  const p = getPos(e);
  ctx?.lineTo(p.x, p.y);
  ctx?.stroke();
  hayFirmaRef.current = true;
}
function stopDraw() {
  dibujandoRef.current = false;
}
function limpiarFirma() {
  const canvas = canvasRef.current;
  const ctx = canvas?.getContext("2d");
  if (canvas && ctx) ctx.clearRect(0, 0, canvas.width, canvas.height);
  hayFirmaRef.current = false;
}

async function enviarFirma() {
  if (enviandoRef.current) return;
  if (!dni.trim()) return setError("Por favor, indique su DNI, NIE o Pasaporte.");
  if (!hayFirmaRef.current) return setError("Por favor, realice su firma en el recuadro.");
  enviandoRef.current = true;
  setError("");
  setEnviando(true);
  // Tiempo máximo de espera: si la red o el servidor no responden, no se queda "Enviando…" indefinidamente.
  const controlador = new AbortController();
  const temporizador = setTimeout(() => controlador.abort(), 60_000);
  try {

    const dataUrl = canvasRef.current?.toDataURL("image/png") || "";
    const firmaBase64 = dataUrl.split(",")[1] || "";
    const res = await fetch("/api/formulario-entrega-venta", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ ventaId, token, dni: dni.trim(), firmaBase64 }),
      signal: controlador.signal,
    });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || "No se pudo registrar la entrega.");
    setYaEstabaEntregado(!!data.yaEntregado);
    setSeccion("exito");
  } catch (e) {
    // Solo si falla se vuelve a permitir enviar; tras un envío correcto el bloqueo se mantiene.
    enviandoRef.current = false;
    setError(
      e instanceof Error && e.name === "AbortError"
      ? "Está tardando más de lo normal. Comprueba tu conexión y vuelve a intentarlo (si ya recibió el correo de confirmación, la entrega está registrada)."
      : e instanceof Error ? e.message : "Error desconocido"
    );
  } finally {
    clearTimeout(temporizador);
    setEnviando(false);
  }
}

return (
  <div style={estilos.body}>
    <div style={estilos.card}>
      {seccion === "cargando" && (
        <div style={estilos.centrado}>
          <div style={estilos.spinner} />
          <p style={{ color: "#6b7280" }}>Cargando datos del pedido…</p>
        </div>
      )}

      {seccion === "error" && (
        <div style={estilos.centrado}>
          <div style={{ fontSize: "3rem", marginBottom: 16 }}>⚠️</div>
          <p style={{ color: "#dc2626" }}>{error}</p>
        </div>
      )}

      {seccion === "cancelado" && (
        <div style={estilos.centrado}>
          <div style={{ fontSize: "3.5rem", marginBottom: 16 }}>⚠️</div>
          <div style={estilos.tituloExito}>Pedido cancelado</div>
          <p style={{ color: "#6b7280", fontSize: ".9rem" }}>
            Este pedido consta como cancelado. Si cree que se trata de un error, contacte con nuestra tienda.
          </p>
        </div>
      )}

      {seccion === "yaEntregado" && (
        <div style={estilos.centrado}>

                onTouchMove={(e) => {
                  e.preventDefault();
                  moveDraw(e);
                }}
                onTouchEnd={stopDraw}
              />
            </div>
            <div style={{ display: "flex", justifyContent: "flex-end", marginBottom: 20 }}>
              <button onClick={limpiarFirma} style={estilos.btnClear}>
                Borrar firma
              </button>
            </div>

            <button onClick={enviarFirma} disabled={enviando} style={estilos.btnSubmit}>
              {enviando ? "Enviando…" : "Confirmar entrega"}
            </button>
            {error && <p style={{ color: "#dc2626", fontSize: ".85rem", marginTop: 12 }}>{error}</p>}
          </>
        )}

        {seccion === "exito" && (
          <div style={estilos.centrado}>
            <div style={{ fontSize: "3.5rem", marginBottom: 16 }}>✅</div>
            <div style={estilos.tituloExito}>{yaEstabaEntregado ? "Firma registrada" : "Entrega confirmada"}</div>
            <p style={{ color: "#6b7280", fontSize: ".9rem" }}>
              Gracias.<br />
              {yaEstabaEntregado
                ? "Su firma ha quedado registrada. El pedido ya constaba como entregado en nuestro sistema."
                : "Le hemos enviado un correo con la confirmación de la entrega."}
              <br />
              ¡Hasta pronto!
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

