function fmtMonto(m: string | null, moneda: string | null) {
  if (!m) return "-";
  return `${Number(m).toFixed(2)} ${moneda || "EUR"}`;
}

/** Puerto fiel de "origenBadge" en renderTabla()/renderFilaConciliada() — mismo pill en Pendientes y Conciliadas. */
