/** "efectivo" / "Efectivo" / " EFECTIVO " — los distintos formularios lo
    guardan con mayúsculas distintas. Un pago combinado ("BBVA · tarjeta
    bancaria") nunca es efectivo. Una factura "multiforma" tampoco es esto
    (puede tener 0 € en efectivo) — ver montoEfectivoDeFactura() para la
    parte que sí hay que contar. */
export function esFormaPagoEfectivo(formaPago: string | null | undefined): boolean {
  return (formaPago || "").trim().toLowerCase() === "efectivo";
}

/** Parte en efectivo de una factura "Multiforma" (Nueva Factura Manual:
    parte en efectivo, parte en otra forma) — la suma de sus entradas
    "efectivo" en el desglose, que ya es el importe real (con IVA incluido,
    validado en el propio diálogo contra el total de la factura). 0 si no
    tiene ninguna parte en efectivo. Sin esto, una factura Multiforma
    quedaba fuera del todo de la vista "Efectivo": su parte en efectivo no
    aparecía en ningún sitio, ni contaba en el saldo de caja real. */
export function montoEfectivoDesglose(formaPagoDesglose: FacturaCliente["formaPagoDesglose"]): number {
  if (!formaPagoDesglose?.length) return 0;
  return redondear(formaPagoDesglose.filter((d) => d.forma === "efectivo").reduce((acc, d) => acc + d.monto, 0));
}

function origenDe(f: FacturaCliente): string {
  if (f.esAlquiler || f.tipo === "alquiler" || f.tipo === "recogida") return "Alquiler";
  if (f.esVenta) return "Venta de piezas";
  if (f.esTicketManual) return "Ticket manual";

  if (f.esManual || f.tipo === "manual") return "Factura manual";
  return "Reparación";
}

function conceptoDe(f: FacturaCliente): string {
  if (f.tipo === "rectificativa" || f.tipo === "corregida") {
    const original =
      f.tipoOriginal === "ticket" || f.tipoOriginal === "ticket_revision" || f.tipoOriginal === "venta_ticket" ? "ticket" : "factura";
    return `${ETIQUETA_TIPO_FACTURA[f.tipo]} de ${original}`;
  }
  const etiqueta = ETIQUETA_TIPO_FACTURA[f.tipo] || f.tipo;
  return f.esTicket && f.tipo === "revision" ? "Ticket de revisión" : etiqueta;
}

function redondear(n: number): number {
  return Math.round(n * 100) / 100;
}

/** Documentos en efectivo → movimientos con signo. */
export function movimientosDeFacturas(facturas: FacturaCliente[]): MovimientoEfectivo[] {
  const out: MovimientoEfectivo[] = [];
  for (const f of facturas) {
    const esMultiforma = (f.formaPago || "").trim().toLowerCase() === "multiforma";
    const montoEfectivoMulti = esMultiforma ? montoEfectivoDesglose(f.formaPagoDesglose) : 0;
    if (!esFormaPagoEfectivo(f.formaPago) && !(esMultiforma && montoEfectivoMulti > 0)) continue;

    // Una "Nueva Factura Manual" con líneas negativas (creada a mano para
    // registrar una devolución, en vez de generarla con el botón
    // "Rectificativa" del sistema) nunca lleva num_factura_rectificativa
    // — expandirManuales() la etiqueta tipo:"manual" igual que cualquier
    // factura normal. Sin esto, su total negativo se contaba en valor
    // absoluto como un COBRO de caja en vez de una devolución (bug real
    // encontrado, 2026-10-06: MANUAL-3-000127/136/139, -200€/-45,29€/-150€
    // sumando de más en "Cobrado" y ausentes de "Devuelto").
    const esDevolucionManualNegativa = f.tipo === "manual" && f.total < 0;
    const esRectificativa = f.tipo === "rectificativa" || esDevolucionManualNegativa;
    // Un documento Pendiente/Anulado aún no ha movido dinero; una
    // rectificativa sí, siempre (es la devolución del cobro original).
    if (!esRectificativa && estadoFacturaDerivado(f) !== "Cobrada") continue;

    // Multiforma: solo la parte en efectivo entra en caja, no el total de

    // la factura (el resto se cobró por otra forma, ya fuera de este libro).
    // Limitación conocida: una rectificativa de una factura Multiforma
    // reutiliza el desglose de LA ORIGINAL entera (el backend no admite hoy
    // un desglose propio por rectificativa) — para una devolución total
    // esto es correcto, pero una rectificativa PARCIAL de una Multiforma
    // devolvería la parte en efectivo completa de la original, no la
    // proporción real de esa devolución parcial.
    const importeAbs = redondear(esMultiforma ? montoEfectivoMulti : Math.abs(montoConIva(f)));
    out.push({
      id: `doc:${f.numero}`,
      fecha: f.fecha,
      tipo: esRectificativa ? "devolucion" : "cobro",
      origen: origenDe(f),
      concepto: esMultiforma ? `${conceptoDe(f)} (parte en efectivo)` : conceptoDe(f),
      referencia: f.resguardo,
      numero: f.numero,
      cliente: f.cliente,
      importe: esRectificativa ? -importeAbs : importeAbs,
      sinImporte: esRectificativa && importeAbs === 0 ? true : undefined,
    });
  }
  return out;
}

export function movimientosDeRetiradas(retiradas: RetiradaEfectivoApi[]): MovimientoEfectivo[] {
  return retiradas.map((r) => {
    // Un ingreso manual (p. ej. el efectivo que ya había en el local) es un
    // cobro normal: suma en "Cobrado" y en la caja, sin tipo propio. Un
    // faltante resta como una retirada, pero con su propio tipo (no se
    // mezcla con las salidas intencionadas en los informes).
    const esCobro = r.tipo === "ingreso";
    const esFaltante = r.tipo === "faltante";
    return {
      id: `ret:${r.id}`,
      fecha: r.fecha_hora,
      tipo: (esCobro ? "cobro" : esFaltante ? "faltante" : "retirada") as TipoMovimientoEfectivo,
      origen: "",
      concepto: (r.motivo || "").trim() || (esCobro ? "Efectivo en caja" : esFaltante ? "Dinero faltante" : "Retirada de efectivo"),
      referencia: "",
      numero: "",
      cliente: "",
      importe: esCobro ? redondear(Number(r.importe) || 0) : -redondear(Number(r.importe) || 0),
      retiradaId: Number(r.id),
      usuario: r.usuario,
      anulada: !!r.anulada_en,
      anuladaMotivo: r.anulada_motivo || undefined,
    };
  });
}

export interface ConteoEfectivoApi {
  id: number | string;
  fecha_hora: string;
  importe_contado: number;
  saldo_sistema: number;
  diferencia: number;
  motivo: string | null;
  usuario: string;
  anulado_en: string | null;
  anulado_por: string | null;
  anulado_motivo: string | null;
}

/** Un conteo compara caja física vs. sistema; nunca mueve dinero (ver
    conSaldoAcumulado/resumir, que lo excluyen a propósito del saldo). */
export function movimientosDeConteos(conteos: ConteoEfectivoApi[]): MovimientoEfectivo[] {
  return conteos.map((c) => {
    const diferencia = redondear(Number(c.diferencia) || 0);
    const notaLibre = (c.motivo || "").trim();
    return {
      id: `cnt:${c.id}`,
      fecha: c.fecha_hora,
      tipo: "conteo" as TipoMovimientoEfectivo,
      origen: "",
      concepto: `Contado ${euros2(c.importe_contado)} · sistema ${euros2(c.saldo_sistema)}${notaLibre ? ` · ${notaLibre}` : ""}`,
      referencia: "",
      numero: "",
      cliente: "",
      importe: diferencia,
      retiradaId: Number(c.id),
      usuario: c.usuario,
      anulada: !!c.anulado_en,
      anuladaMotivo: c.anulado_motivo || undefined,
      saldoSistema: redondear(Number(c.saldo_sistema) || 0),
    };
  });
}

function euros2(n: number): string {
  return (Number(n) || 0).toLocaleString("es-ES", { style: "currency", currency: "EUR" });
}

export interface MovimientoConSaldo extends MovimientoEfectivo {
  /** Saldo de caja tras este movimiento (sobre TODO el historial, no solo
      el rango filtrado). */
  saldo: number;
}

/** Ordena cronológicamente, calcula el saldo acumulado (las retiradas
    anuladas no cuentan; un conteo nunca cuenta, solo verifica) y devuelve
    la lista más reciente primero. */
export function conSaldoAcumulado(movimientos: MovimientoEfectivo[]): MovimientoConSaldo[] {
  const ascendente = [...movimientos].sort((a, b) => {
    const ta = a.fecha ? new Date(a.fecha).getTime() : 0;
    const tb = b.fecha ? new Date(b.fecha).getTime() : 0;
    return ta - tb || a.id.localeCompare(b.id);
  });
  let saldo = 0;
  const out = ascendente.map((m) => {
    if (!m.anulada && m.tipo !== "conteo") saldo = redondear(saldo + m.importe);

    return { ...m, saldo };
  });
  return out.reverse();
}

export interface ResumenEfectivo {
  cobros: number;
  devoluciones: number;
  retiradas: number;
  neto: number;
}

/** Totales de una lista de movimientos (devoluciones/retiradas en positivo,
    para poder mostrarlas como "− X" sin doble negación). Un conteo no suma
    ni resta aquí: no es un cobro ni una salida real de caja. */
export function resumir(movimientos: MovimientoEfectivo[]): ResumenEfectivo {
  let cobros = 0;
  let devoluciones = 0;
  let retiradas = 0;
  for (const m of movimientos) {
    if (m.anulada || m.tipo === "conteo") continue;
    if (m.tipo === "cobro") cobros += m.importe;
    else if (m.tipo === "devolucion") devoluciones += -m.importe;
    else retiradas += -m.importe;
  }
  return {
    cobros: redondear(cobros),
    devoluciones: redondear(devoluciones),
    retiradas: redondear(retiradas),
    neto: redondear(cobros - devoluciones - retiradas),
  };
}

