/**
 * Un móvil/fijo español real son siempre 9 dígitos. El formulario público y
 * "Aceptar ahora" autocompletan el teléfono a partir del cliente ya
 * guardado (buscarClientePorDni/separarTelefono): si ese valor guardado ya
 * traía un "34" de más pegado al número (dato corrompido de un envío
 * anterior), el siguiente envío lo volvía a combinar con el prefijo del
 * selector y quedaba "34" otra vez de más — creciendo sin límite en cada
 * ciclo (34 → 3434 → 343434… detectado en producción). Esta función se usa
 * tanto al autocompletar (para no perpetuar el dato ya corrompido) como al
 * guardar (para no dejar que se generen números nuevos así de largos).
 */
export function normalizarNumeroLocal(prefijo: string, numeroDigits: string): string {
  if (prefijo === "+34" && numeroDigits.length > 9) return numeroDigits.slice(-9);
  return numeroDigits;
}

/**
 * El texto que llega como "respuesta del cliente" (webhook de n8n) suele
 * ser el email completo del cliente, con la cabecera de cita que añade el
 * propio cliente de correo ("On [fecha] [hora] Kelatos Servicio Técnico
 * <soporte@kelatos.com> wrote:" / equivalente en español "El ... escribió:")
 * seguida del hilo citado — nunca la enviamos nosotros, viene ya así en la
 * respuesta original. Se corta ahí para mostrar solo lo que el cliente
 * escribió de verdad (bug real reportado, 2026-09-01: se mostraba todo
 * junto, ilegible).
 */
const PATRON_CITA_CORREO = /\bOn\s+.{5,120}\bwrote:|\bEl\s+.{5,120}\bescribi[oó]:/i;

export function limpiarRespuestaCliente(texto: string | null | undefined): string {
  if (!texto) return "";
  const m = texto.match(PATRON_CITA_CORREO);
  const limpio = m && m.index !== undefined ? texto.slice(0, m.index) : texto;
  return limpio.trim();
}

